window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_018"]={"n":"胤禛","dyn":"清","poems":[{"t":"清凉纪游一十四首 其一 入山","f":"七言律诗","c":["清凉境界梵王宫，碧染芙蓉耸昊穹。","万古云封五顶寺，千株松纳四时风。","盘回鸟道珠幡里，缭绕炉烟画障中。","石立俨然如接引，疑逢青髻化身童。"]},{"t":"春园读书","f":"七言律诗","c":["一片芳菲上苑东，昼长人坐落花风。","蒙茸细草侵阶绿，浓艳夭桃映阁红。","香惹游蜂窥几席，晴熏舞蝶傍帘栊。","韶光脉脉春如海，讽咏芸编兴不穷。"]},{"t":"瞻仰盛京宫阙念祖宗创业艰难恭赋二十韵","f":"五言古诗","c":["奉命趋辽海，猗欤仰旧宫。","逶迤龙脉远，詄荡凤城雄。","念昔开洪造，乘时建武功。","师征方自葛，考卜重迁酆。","一剑风尘际，三陲指顾中。","神威宣率土，皇极协苍穹。","式廓弥增壮，维垣遂克崇。","八门连阃域，双阙竦高空。","曳佩千官列，输琛万国同。","兵农咸定制，礼乐渐移风。","爰及纯熙介，覃敷景历融。","寰区欣奠鼎，故里抱遗弓。","沛邑恩优渥，舂陵望郁葱。","星躔争拱北，王气本从东。","绵瓞钟灵盛，凝庥后裔蒙。","圣慈殷孝享，敕谕遣微躬。","肃睹兴京胜，恭承祀典隆。","丕基劳栉沐，奕叶荷帡幪。","槚松灵祗护，檐楹肸蚃通。","祖宗光烈在，明发惕愚衷。"]},{"t":"望岱","f":"七言律诗","c":["芙蓉万仞插丹梯，海上群峰莫与齐。","九点青烟看野马，五更红日候天鸡。","云封峭壁松多古，藓积残碑字未迷。","冉冉岭头笙鹤下，仙坛曾此降金泥。"]},{"t":"世宗宪皇帝御制耕耤乐章三十六禾词雍正二年","f":"七言古诗","c":["光华日月开青阳。","房星晨正呈农祥。","帝念民依重耕桑。","肇新千耤考典章。","吉蠲元辰时日良。","苍龙銮略临天阊。","青坛峙立西南方。","牺牲簠簋升芬芳。","皇心祇敬天容庄。","黄幕致礼虔诚将。","礼成移跸天田旁。","土膏沃洽春洋洋。","黛犁行地牛服缰。","司农种稑盛青箱。","洪縻在手丝鞭扬。","率先稼穑为民倡。","三推一垡制有常。","五推九推数递详。","王公卿尹咸赞襄。","甸人千耦列雁行。","耰锄既毕恩泽滂。","自天集福多丰穰。","来牟荞芲森紫芒。","华芗赤甲籼杆䄱。","秬秠三种黎白黄。","稷粟坚好硕且香。","糜芑大穗盈尺长。","五菽五豆充垄场。","穄粢糜黎九色粮。","蜀秫玉黍兼东廧。","鸟禾同收除童粱。","双歧合颖遍理疆。","千箱万斛收神仓。","四时顺序百谷昌。","八区九有富盖藏。","欢腾亿兆感圣皇。"]},{"t":"早起寄都中诸弟","f":"七言律诗","c":["晓起轻寒透薄帷，风光节物暗推移。","正当边塞秋临早，况是关山月落迟。","一雁孤鸣惊旅梦，千峰攒立动诗思。","凤城诸弟应相忆，好对黄花泛酒卮。"]},{"t":"山居偶成","f":"七言律诗","c":["山居且喜远纷华，俯仰乾坤野兴赊。","千载勋名身外影，百年荣辱镜中花。","金樽潦倒春将暮，蕙径葳蕤日又斜。","闻道五湖烟景好，何缘蓑笠钓汀沙。"]},{"t":"暮春","f":"五言律诗","c":["春暮饶佳景，闲行踏碧苔。","落花浮水面，戏蝶舞墙隈。","春拂兰丛暖，阴移竹影回。","流光将入夏，更有牡丹开。"]},{"t":"山翁","f":"七言绝句","c":["山翁避暑在山中，竹簌松涛面面风。","三乐启期何所事，朝阳睡到夕阳红。"]},{"t":"渔翁","f":"七言绝句","c":["渔翁独钓曲江湾，春雨秋风总是闲。","满眼儿孙长绕膝，卖鱼沽酒醉苍颜。"]},{"t":"山池晚步","f":"七言律诗","c":["夕阳斜映绿波清，闲傍长桥步屧行。","山静鹿过衔瑞草，溪平鱼泳趁飞英。","濛濛岚气侵衣润，款款香风扑面轻。","徒倚景光天欲暮，凌虚楼阁带霞明。"]},{"t":"咏自鸣钟","f":"五言律诗","c":["巧制符天律，阴阳一弹包。","弦轮旋密运，针表恰相交。","晷刻毫无爽，晨昏定不淆。","应时清响报，疑是有人敲。"]},{"t":"春日泛舟","f":"七言律诗","c":["兰舟宛转浪纹平，一棹容与荡晚晴。","上苑春深芳草绿，西山落照远峰明。","长空鸦返千林暝，绝塞鸿归万里情。","缥缈中流凭览胜，始知仙境有蓬瀛。"]},{"t":"夜坐","f":"五言律诗","c":["独坐幽园里，窗开竹影斜。","稀闻更转漏，但听野鸣蛙。","活活泉流玉，溶溶月照沙。","悠然怡静境，把卷待烹茶。"]},{"t":"春暮登楼","f":"五言律诗","c":["坐惜芳华晚，登楼独举觞。","眼看春色暮，行踏落花香。","藻密鱼堪隐，林深鸟易藏。","凭栏无限思，新月逗清光。"]},{"t":"月夜对落花有感","f":"七言律诗","c":["落花满径月朦胧，夜静闲吟料峭风。","烟外钟声来院落，天边桂影入帘栊。","萋萋芳草春将去，冉冉韶光酒莫空。","新绿成阴红紫减，清和天气正冲融。"]},{"t":"月下独酌","f":"七言绝句","c":["春月娟娟映水清，一斟一酌听泉声。","微风暗拂花枝动，几点残红扑酒罂。"]},{"t":"春院小饮","f":"七言绝句","c":["春深红紫映楼台，槛外风香花尽开。","东海玉盘看乍涌，恰逢童子抱尊来。"]},{"t":"雨霁","f":"七言绝句","c":["节届清和春未赊，看山不厌半云遮。","微风扇暖蒸新雨，为我催开后院花。"]},{"t":"立夏","f":"七言绝句","c":["熏风吹水绿于苔，羲驭徐催朱夏来。","堤畔龙鳞皴古柏，庭前兔目绽新槐。"]},{"t":"畅春园芍药花开作","f":"七言律诗","c":["首夏清和殿阁开，园中景物足徘徊。","翩翾紫燕衔泥去，睍睕黄莺过水来。","槐影初圆当永昼，桐阴渐引上层台。","更怜芍药临风好，香袭书帏锦作堆。"]},{"t":"花间小饮","f":"七言绝句","c":["长夏初临芍药开，熏风拂席送香来。","仙姿绰约翻红袖，月影婆娑照绿杯。"]},{"t":"晓晴","f":"七言律诗","c":["晓起浮窗日色明，苔痕滋碧露光莹。","绕阶几树看花发，对岸一声听鸟鸣。","波剌游鱼翻浪急，低徊舞蝶傍帘轻。","春云漠漠寒偏峭，默乞天公十日晴。"]},{"t":"宫中直宿作","f":"五言律诗","c":["宝殿烛辉煌，承恩宿未央。","御炉香不烬，宫漏滴初长。","阶砌移花影，罘罳透月光。","太平无一事，常愿奉君王。"]},{"t":"夏日读书","f":"五言绝句","c":["夏日书斋静，荷风拂槛来。","芬芳盈几席，翠帙带香开。"]},{"t":"早行","f":"七言律诗","c":["早行晴野树如烟，日出东山映绣鞯。","寂寂荒村临水际，翩翩飞鸟向云边。","空濛朝露侵衣润，艳冶闲花入目妍。","扈从銮舆承色笑，欣随豹尾快扬鞭。"]},{"t":"江边书屋","f":"五言绝句","c":["湍响听泷泷，帘开对大江。","园幽人迹少，把卷倚南窗。"]},{"t":"晚登海河楼","f":"五言律诗","c":["晚景登楼望，波涵夕照明。","观澜清俗虑，倚槛动诗情。","孤鹜冲霞去，扁舟向海行。","悠然尘境远，惟听棹歌声。"]},{"t":"题友人园","f":"五言律诗","c":["峁堂气象幽，墙角绕清流。","雨霁西山近，风来北牖秋。","疏檐看皓月，轻舫逐浮鸥。","即景陈杯斝，心期好自由。"]},{"t":"赐观金莲花","f":"七言律诗","c":["异种遥从塞外传，香台曾为捧金仙。","檀心吐艳熏风里，钿朵含芳积翠边。","月殿桂飘难比瑞，秋篱菊绽不同妍。","移来御砌增佳玩，千叶休夸太液莲。"]},{"t":"友人书屋","f":"七言绝句","c":["羡君潇洒致如仙，心远何妨地更偏。","雨洗岚光青入牖，风摇竹影绿当筵。"]},{"t":"雨窗","f":"五言绝句","c":["茅檐飞细雨，爽气乍侵人。","移榻临窗坐，诗怀自觉新。"]},{"t":"热河园中避暑","f":"七言绝句","c":["别业遥连上苑边，承恩避暑兴怡然。","兰舟晓泛清波里，荷盖擎珠颗颗圆。"]},{"t":"夏日泛舟","f":"七言绝句","c":["殿阁风生波面凉，溯洄徐泛芰荷香。","柳阴深处停桡看，无数纤鯈戏碧塘。"]},{"t":"园中即景","f":"七言绝句","c":["林亭幽静晚风凉，水气侵衣荇藻香。","好景片时期莫负，开窗披卷意徜徉。"]},{"t":"晚泛","f":"七言绝句","c":["画桡闲泛暮霞明，风细波微暑气轻。","更转碧山寻胜迹，恰逢双鹤似相迎。"]},{"t":"月下闲步","f":"五言律诗","c":["闲行曲岸边，西岭暮苍然。","草蔓迷幽径，桥危咽细泉。","溪风吹缓带，夜色逼吟肩。","徙倚看林杪，云间月影迁。"]},{"t":"观雨","f":"七言绝句","c":["密雨如膏洒碧丝，稻花漠漠绕长陂。","虚斋睡起推窗看，私喜甘霖正及时。"]},{"t":"前廊","f":"七言律诗","c":["曲廊斜转接修篁，坐倚层岩意兴长。","细草敷荣侵塌绿，野花争艳袭衣香。","碧梧枝上听蝉躁，翠柳堤边看鹤翔。","此际闲身无一事，怡然啸咏自徜徉。"]},{"t":"书斋秋暝","f":"五言律诗","c":["幽斋新雨后，爽气泛池荷。","碧落疏星淡，晴窗皓月多。","隔花闻漏滴，倚枕和渔歌。","更爱流萤好，悠扬拂槛过。"]},{"t":"恭侍奉乾清宫","f":"七言律诗","c":["殿阁参差际碧天，玉阶秋草静芊绵。","云开北阙祥光满，雨过西山霁色鲜。","宝座金炉香蔼蔼，彤墀仙掌露涓涓。","承欢频荷温颜接，凛惕趋跄绣扆前。"]},{"t":"中元侍从","f":"七言律诗","c":["中元令节庆皇州，云散晴空暑气收。","薄海兆民歌大有，钧天广乐奉宸游。","瑶星合彩兰盆映，银蕊分光莲浦浮。","灯光交辉看似昼，圣情怡豫太平秋。"]},{"t":"运河舟中二首 其一","f":"五言律诗","c":["扈跸乘文舸，沿流阅运河。","晓窗飘白絮，夜岸沐金波。","酒幔篱边扬，渔舟苇畔歌。","长途看美景，偏觉此中多。"]},{"t":"运河舟中二首 其二","f":"五言律诗","c":["解缆放中流，晨光漾桂舟。","远村烟淡淡，野老意悠悠。","抛粒游鱼聚，依萍乳鸭浮。","水天同一色，疑是泛瀛洲。"]},{"t":"登望海楼","f":"七言律诗","c":["观海登楼日未斜，晴空万里浮云霞。","才经一阵风过槛，倏起千堆雪卷花。","贝阙鳌峰如可接，鹏津鲛室岂终遐。","诡词未许张融赋，到此方知语不夸。"]},{"t":"自鸣钟","f":"五言律诗","c":["八万里疏域，恩威悉感通。","珍奇争贡献，钟表极精工。","应律符天建，闻声得日中。","莲花空制漏，奚必老僧功。"]},{"t":"咏玉泉山竹","f":"七言律诗","c":["御园修竹传名久，嫩筱抽梢早出墙。","雨涤微尘新浥翠，风穿密叶澹闻香。","低侵幽涧波添绿，静幂虚窗影送凉。","更羡坚贞能耐雪，长竿节节挺琳琅。"]},{"t":"秋夜","f":"七言绝句","c":["新秋秋月照虚檐，寂历山扉夜不关。","默坐焚香遗万虑，潇潇梧竹水潺湲。"]},{"t":"晚晴","f":"七言绝句","c":["雨余林隙漏斜曛，石砌幽花似茜裙。","爽气渐来残暑退，移床岩畔看秋云。"]},{"t":"听禅","f":"五言律诗","c":["幽斋人迹少，禅翼响疏林。","大火方流序，微凉早托音。","乍听分远近，欲觅隐高深。","旦夕轩亭外，清机伴我吟。"]},{"t":"题刘松年画","f":"五言律诗","c":["潇洒松年画，丰神迥不群。","松杉相间秀，风水自成文。","柔橹轻随浪，苍山半入云。","超然三岛境，何处得尘氛？"]},{"t":"临流","f":"七言律诗","c":["脉脉清渠绕舍流，移床就柳坐溪头。","镜涵霁影浮斜日，波映寒光报早秋。","村畔砧声听渐暝，林端蝉翼噪逾幽。","此中偃息容疏懒，底用乘槎海上游。"]},{"t":"扈跸途中观获","f":"五言律诗","c":["秋爽猎边城，天高气象清。","登场占物候，观获畅皇情。","岩谷萦车骑，云霞拂旆旌。","豫游叨扈从，薄劣愧恩荣。"]},{"t":"塞外中秋","f":"五言律诗","c":["驻跸边庭夜，中秋一镜圆。","遥从沧海畔，飞落碧峰颠。","溢彩浮尧斝，流辉拂舜弦。","坐深光愈迥，景物倍清妍。"]},{"t":"大猎","f":"五言律诗","c":["五校雕工劲，三秋野兽肥。","乘时讲武事，大狝振兵威。","狡兔宁藏迹，封熊悉入围。","猎归数军实，落日照龙旂。"]},{"t":"塞外秋兴二首 其一","f":"五言律诗","c":["路出关山外，秋空日渐高。","清霜凝晓旆，寒色透征袍。","风劲飞鹰捷，川长猎骑豪。","皇威扬四远，边徼戢弓刀。"]},{"t":"塞外秋兴二首 其二","f":"五言律诗","c":["驻跸依林麓，风多野水鸣。","旌旗飘暮霭，铙吹咽边声。","鸡塞霜逾白，龙沙风更清。","却看行殿外，诸部尽欢迎。"]},{"t":"题范蠡载归图","f":"五言古诗","c":["独有艰危时，方见子臣职。","吴越争雌雄，彼此各努力。","夫差好拒谏，只为红颜惑。","所以范大夫，留之恐倾国。","功成载归湖，斯意无人识。","朗然照青史，去往皆可式。"]},{"t":"答友","f":"七言绝句","c":["笔健如锥世共称，开缄但觉雾云兴。","深藏未许悬斋壁，直恐龙蛇带雨腾。"]},{"t":"瀛台泛舟二首 其一","f":"五言律诗","c":["春深游上苑，鼓枻荡中流。","波涌方壶岛，林开翡翠楼。","落花飘两岸，垂柳拂扁舟。","此日欢无极，君恩被特优。"]},{"t":"瀛台泛舟二首 其二","f":"五言律诗","c":["暮转西池棹，风微锦波平。","蜻蜓闲自得，鸂鶒递和鸣。","举网双鳞获，停杯四韵成。","仙山何处访？","此即是蓬瀛。"]},{"t":"即事","f":"五言律诗","c":["当昼垂帷静，晴和景物佳。","铺笺摹古帖，披卷畅幽怀。","槛外花香度，帘前燕语谐。","日长真似岁，绿竹伴虚斋。"]},{"t":"初夏至玉泉山","f":"五言律诗","c":["绿野熏风至，夜来春已过。","扑衣飘落絮，贴水出新荷。","浪暖鱼吹沫，泥香燕作窠。","林泉聊命酒，披拂爱烟萝。"]},{"t":"书斋坐雨","f":"五言律诗","c":["长夏书斋静，云低拂讲帷。","竹风扫翠石，荷雨滴清池。","逸兴开新酿，闲情检旧诗。","晚凉生几席，团扇不须披。"]},{"t":"午日","f":"七言律诗","c":["天中节届日逾赊，解愠熏风透薄纱。","处处相酬三角黍，家家笑馈五时花。","薄觞引满巡筵转，桂楫如飞竞渡哗。","四海纤邪消影迹，佩符何用绘丹砂。"]},{"t":"便殿恭侍","f":"七言律诗","c":["承欢便殿接天香，披拂熏风爱日长。","时雨连朝滋稻垄，晴霞一片映湖光。","凛遵圣训闻诗礼，勉竭愚忱效颂扬。","浩荡恩波沦亿兆，衢歌喜听祝无疆。"]},{"t":"狼居胥山大阅","f":"五言古诗","c":["帝为生民计，狼胥阅大兵。","穷荒金鼓震，朔漠旆旌明。","令出山川动，威扬神鬼惊。","技娴百战勇，恩重一身轻。","预卜妖氛散，悬知海宇清。","彼狂擒子献，蠢尔倒戈迎。","遁去浑无路，争归尽布诚。","鹰抟驱鸟伏，螳臂骇车行。","不惮疏方远，惟期边塞平。","濡毫歌懋烈，吉日愧难赓。"]},{"t":"功成回銮恭颂二首 其一","f":"五言律诗","c":["指顾靖边烽，怀生尽服从。","遐荒归禹甸，大漠纪尧封。","庙算无遗策，神功迈昔踪。","凯旋旌耀日，光景霁天容。"]},{"t":"功成回銮恭颂二首 其二","f":"五言律诗","c":["翠华旋万里，即日解征袍。","共仰神机邃，深维圣体劳。","凯歌喧后队，巷舞迓前旄。","拓土无中外，皇猷协覆帱。"]},{"t":"扈跸山行","f":"五言律诗","c":["紫塞秋山丽，霜枫锦作堆。","草深麋鹿伏，风急雁鸿来。","瀑水穿林响，寒花向日开。","忻随清跸后，揽辔重徘徊。"]},{"t":"塞外观稼","f":"五言律诗","c":["边陲环沃壤，树艺遍皋阳。","东作频沾雨，西成未陨霜。","两岐占瑞应，遗秉见丰穰。","比户盈宁日，衢歌感圣皇。"]},{"t":"观鱼","f":"五言律诗","c":["羽卫随行幄，逶迤绿水隈。","棹分寒藻入，波涌锦鳞来。","网罟无空举，鳣鲂自暴腮。","烹鲜供御馔，竟日豫清徊。"]},{"t":"冬日圣驾自塞外回銮谒陵恭纪","f":"五言律诗","c":["威德绥荒服，乘舆按部回。","欢声盈朔漠，瑞蔼被龙堆。","鞭拂霜花净，旗飘野吹开。","更遵丰沛路，陵殿荐尊罍。"]},{"t":"陪京","f":"五言律诗","c":["新丰传旧里，今睹濯龙池。","天地开神奥，山河启帝基。","金戈劳百战，玉叶衍千枝。","追远皇情切，趋从仰孝思。"]},{"t":"侍从兴京谒陵二首 其一","f":"五言律诗","c":["承先崇报本，桥道驻龙旗。","万国梯航集，敷天雨露随。","精诚通寝殿，肃穆奉宗彝。","敬仰松楸古，昭森盛烈垂。"]},{"t":"侍从兴京谒陵二首 其二","f":"五言律诗","c":["龙兴基景命，王器结瑶岑。","不睹艰难迹，安知启佑心。","山河陵寝壮，弓剑岁时深。","盛典叨陪从，威仪百尔钦。"]},{"t":"登望海楼","f":"五言律诗","c":["极目澹沧海，涵泓无所从。","量包天地外，色染古今容。","浪起思鲲化，云飞羡鹤踪。","坐观渊默里，万派自朝宗。"]},{"t":"皇父勘河省不获奉侍瞻恋惭悚交迫于怀敬成一律","f":"五言律诗","c":["河槽筹国计，疏导恤民生。","俯允廷臣请，亲劳圣主行。","未能随法驾，何以效愚情。","定省无由达，中宵愧悚并。"]},{"t":"圣驾南巡自春徂夏瞻依心切恭赋斯篇","f":"七言律诗","c":["春光荏苒熏风至，圣驾勤民尚未还。","幸有埙篪随越舸，愁无羽翼赴吴关。","晨趋北阙螭头上，夜梦南云豹尾闲。","清陛恭迎堪计日，几回翘首潞河湾。"]},{"t":"皇父亲祀北郊甘霖大霈恭纪","f":"五言律诗","c":["甫竣宣防略，銮回五月中。","郊原需惠雨，稼穑切皇衷。","方泽期将界，精禋事必躬。","礼成霖澍霈，圣意信天通。"]},{"t":"雨后即事","f":"五言律诗","c":["雨足适新晴，翛然天宇清。","殷忧舒北阙，栉比望西成。","殿阁微风度，阶除残暑轻。","濡毫思志喜，禾黍竞滋荣。"]},{"t":"立秋日怡情亭","f":"七言律诗","c":["亭引微风暑气蠲，碧空如洗净云烟。","地饶佳景供清赏，节送新凉称午眠。","几处蝉鸣啁积翠，数行鱼队乐漪涟。","谁云秋色多萧瑟，无限青山入目妍。"]},{"t":"孟秋扈跸观稼恭纪","f":"五言律诗","c":["殿角微凉起，豳歌大火流。","莲房新坠粉，梧叶早惊秋。","玉露滋芳甸，金风入画楼。","圣心勤稼穑，躬自省西畴。"]},{"t":"赋得一轮寒月照书橱","f":"五言律诗","c":["灿烂书千卷，莹然一镜悬。","映签光潋潋，透幌影娟娟。","秘阁搜奇字，芸窗理旧编。","夜深看愈皎，清坐懒成眠。"]},{"t":"冬日早朝","f":"七言律诗","c":["星疏紫禁启金扉，银烛辉煌映琐闱。","钟鼓声催仙仗肃，虹蜺影逐彩旗飞。","寒风几度轻摇佩，瑞雪初飘乍点衣。","喜睹太平文物盛，天香满袖早朝归。"]},{"t":"雪夜即事","f":"五言律诗","c":["永夜漏方中，琼瑶洒半空。","气侵书幌冷，光闪烛花红。","兴洽张琴好，心清得句工。","诘朝恭省候，披拂玉阶风。"]},{"t":"元夕","f":"七言律诗","c":["皓月高悬不夜城，灯辉万井庆升平。","臣民语和嵩山语，喧笑声连爆竹声。","火树拂云飞赤凤，琪花满地落丹英。","金吾弛禁欢游剧，载路笙歌直到明。"]},{"t":"咏黄河灯","f":"五言律诗","c":["华灯夜满原，布置列星繁。","缥缈探三岛，离奇演八门。","旌旗随火转，语笑逐风喧。","寓意藏韬略，游观荷圣恩。"]},{"t":"早春","f":"五言律诗","c":["冻解和风至，璇杓正建寅。","丛梅初绽玉，余雪已销银。","柳眼窥人近，莺声到耳新。","须知迎日处，应早被阳春。"]},{"t":"舟次","f":"五言律诗","c":["扈跸阅长河，微风起碧波。","牙樯连百里，珠旆转层坡。","拂几调琴韵，临窗听棹歌。","时清多乐事，万汇总春和。"]},{"t":"晚泊","f":"五言律诗","c":["傍柳泊湖船，停桡薄暮天。","远村烟树里，归雁水云边。","钓叟垂香饵，樵童曳纸鸢。","江乡民物美，风景更熙然。"]},{"t":"顺风放舟","f":"五言律诗","c":["长河风力驶，千里片帆轻。","桨歇村频转，桡停岸自迎。","野凫冲荇起，归雁拂云鸣。","试问邮亭吏，何如驷马行。"]},{"t":"天津舟中对月","f":"五言律诗","c":["初月照扁舟，潮声洗客愁。","孤村一树矗，隔岸数帆收。","霄汉闻鸣雁，沙汀玩宿鸥。","渔歌入夜寂，风景似清秋。"]},{"t":"水围","f":"五言律诗","c":["春日猎汀洲，欢声拍浪浮。","云樯排八阵，桂棹竞中流。","鸣镝摧腾羽，飞烟罨彩斿。","昆明夸水舰，岂足拟宸游。"]},{"t":"春日潞河","f":"五言律诗","c":["潞河初解冻，桂楫溯潆洄。","霁色明书帙，春涛劝酒杯。","云排群鸟度，风鼓万帆开。","扈从轩游日，惟惭作赋才！"]},{"t":"春日随驾舟次","f":"五言律诗","c":["新柳绿丝柔，依依拂御舟。","悠扬牛背笛，款乃水边讴。","翠羽飞桑扈，娇音啭栗留。","春晴天气好，欢喜奉宸游。"]},{"t":"园居","f":"七言律诗","c":["十分春色属清明，翠积岚光媚晓晴。","帘幕争飞村社燕，池台巧啭上林莺。","青丝摇曳萦烟槛，红雨霏微扑绣楹。","赋罢小诗清昼永，闲随白鹤柳边行。"]},{"t":"春郊","f":"五言律诗","c":["策马向春田，闲游野趣偏。","飞花时点袂，舞蝶故随鞭。","萍密藏溪鹜，风高戾纸鸢。","酒旗遥入望，茅店古松边。"]},{"t":"阅永定河应制","f":"五言律诗","c":["帝念切民生，銮舆冒暑行。","绕堤翻麦浪，隔柳度莺声。","万姓资疏浚，群工受准程。","圣心期永定，河伯助功成。"]},{"t":"巡子牙河建坝应制","f":"五言律诗","c":["承恩随鹢首，私幸睹皇猷。","躬定安澜策，民无昏垫忧。","秧针抽覆陇，梅雨洒良畴。","勉效河平颂，多惭士女讴。"]},{"t":"恭睹圣心勤劳颂扬不尽又成长句","f":"七言律诗","c":["叨陪法驾阅新堤，夙夜辛勤悯庶黎。","底定九河功媲美，时巡三辅典堪稽。","烟村黯黯青帘扬，岸柳阴阴白马嘶。","沉璧寘薪诚默契，神人应有绿图携。"]},{"t":"秋日","f":"七言律诗","c":["淅沥金风暑渐收，园林景物足清幽。","青山环列遥如画，云汉斜晖望欲流。","露咽寒蛩声唧唧，月明野鹤意悠悠。","丰年不用农人告，手把香粳验有秋。"]},{"t":"作书","f":"七言绝句","c":["搦管曾闻渴骥奔，鱼笺挥洒墨香痕。","虽惭腕弱无佳致，净几明窗颂圣恩。"]},{"t":"荷花","f":"五言律诗","c":["玉井移根种，亭亭曲沼中。","红衣初坠粉，翠盖晚摇风。","隔浦纤歌隐，回塘丽影同。","彩鸳双泳处，珠露泻香丛。"]},{"t":"对月","f":"七言绝句","c":["新秋玉露洗长空，冰镜孤悬映绮栊。","一片清光凉似水，万年宫树照青葱。"]},{"t":"秋雨","f":"五言律诗","c":["一雨收残暑，微凉发树端。","风清催早桂，气洁媚幽兰。","曲沼波痕涨，平畴稻颖繁。","诗成晚霁后，秋月逗烟峦。"]},{"t":"驾幸新园","f":"五言律诗","c":["警跸临山墅，仙云拂晓来。","池台增景色，旌盖仰昭回。","野鸟迎銮舞，闲花傍辇开。","歌惭鱼藻咏，赋乏上林才。"]},{"t":"宫中秋日应制","f":"七言律诗","c":["九重殿阁卿云绕，鸳瓦参差丽曙晖。","北阙轻阴连琐闼，西山爽气裛彤闱。","疏桐转影遥迎盖，早桂含香乍拂衣。","欲颂高深言莫罄，朝朝惭戴圣恩归。"]},{"t":"皇父颁赐御制诗扇恭纪","f":"七言律诗","c":["慈恩莫并与天崇，御制遥颁宠锡隆。","挥洒仙毫凝湛露，捧摇宝扇被仁风。","四诗寻绎宸章里，八体兼收睿笔中。","圣蕴难窥真万仞，于兹力学愿磨砻。"]},{"t":"禁苑秋霁应制","f":"五言律诗","c":["灵囿逢秋霁，西山晓翠张。","澄波添太液，爽气发长杨。","丛桂含香嫩，疏桐转影凉。","宸襟披拂处，鱼藻有辉光。"]},{"t":"望海楼二首 其一","f":"七言律诗","c":["凌霄雄杰耸层楼，碧海苍茫远望收。","混一乾坤云水阔，濯磨日月浪花浮。","百川输委盈襟带，万类涵濡任泳游。","闻道此中覃帝泽，几曾汪秽有停流。"]},{"t":"望海楼二首 其二","f":"七言律诗","c":["朱栏画栋最高楼，海色天容万象收。","海底鱼龙应变化，天中云雨每蒸浮。","无波不具全潮势，此日真成广汉游。","仙客钓鳌非我意，凭轩惟是羡安流。"]},{"t":"晓度杏山","f":"五言律诗","c":["曙色催樵牧，山崖径郁盘。","霜凝鸦背白，沙印马蹄干。","海气笼朝旭，林飙送早寒。","凤城清漏隔，遥忆寝门安。"]},{"t":"望医巫闾山","f":"五言律诗","c":["翠黛满云封，遥看北镇雄。","壮观侔五岳，峻秩比三公。","葱郁兴王气，扶摇广莫风。","勒铭维祖烈，瞻仰万年同。"]},{"t":"渡句骊河","f":"五言律诗","c":["辽水东西岸，寒云接渺茫。","平沙留雁迹，堠火靖龙荒。","木落晴峦出，冰坚雪练长。","经时疏定省，望日陡高冈。"]},{"t":"谒福陵恭颂","f":"七言律诗","c":["一峰天柱象昆仑，圣武开基百世尊。","庙貌辉煌茂剑舄，尘氛荡涤辟乾坤。","赤龙遐举云留影，石马宵趋汗渍痕。","赫濯声灵通僾肃，春秋霜露感长存。"]},{"t":"谒昭陵恭颂","f":"七言律诗","c":["钟灵毓秀气佳哉，宇宙从兹景运开。","帝统兼因文治广，圣基岂独武功恢。","辽韩海水涵深泽，松杏山高接上台。","虔肃奉觞恭拜毕，五云飞处久徘徊。"]},{"t":"避暑口外","f":"七言律诗","c":["爽垲高原古上都，郁蒸节候热全无。","千寻木荫招凉扇，几道泉飞辟暑珠。","时任镂冰为鸟兽，湾从销夏泛菰蒲。","何如此地随仙跸，披拂清风胜舞雩。"]},{"t":"口外山村","f":"五言律诗","c":["鸟外窥烟树，微茫碛路斜。","地寒宜种黍，坡暖好栽瓜。","比户裁驼褐，居人置兔罝。","谁将淳朴意，传写入中华？"]},{"t":"田家即事二首 其一","f":"七言绝句","c":["沙碛高低禾黍盈，群飞铜雀绕田鸣。","竹弓蒿矢堪驱吓，漫向黄云试射声。"]},{"t":"田家即事二首 其二","f":"七言绝句","c":["戍烽罢举息征尘，肆力耕耘属幸民。","榆柳阴疏秋社近，缘边笳鼓赛田神。"]},{"t":"中秋从猎塞外","f":"七言律诗","c":["万里清辉度塞寒，一轮飞镜耀云端。","穹庐影静金波蘸，行漏声沉玉露漙。","光射龙沙明远碛，香飘仙桂拂层峦。","普天今夕同忻赏，何似趋承膝下欢。"]},{"t":"金莲花","f":"五言古诗","c":["菡萏敷鲜彩，绚烂云锦重。","茜裳杂缟袂，擢艳白复红。","根株遍陂泽，名品将无同。","昔传天竺师，钵咒青芙蓉。","非关造物力，色相自虚空。","独有金莲号，图谱考莫从。","我来古塞北，野卉竞丰茸。","罗生岩谷底，琐屑焉能穷？","灿然睹奇葩，谁施冶铸工！","六丁鼓炉鞴，几费丹阳铜。","镂刻成千瓣，片片黄金熔。","碧茎袅翠叶，挺出薰风中。","俨如九品台，宝络垂玲珑。","金仙此趺坐，演偈降狞龙。","幽芳宜见赏，辇路会当逢。","亭亭黄屋侧，照耀衔壁釭。","宸游每披拂，香气向日融。","愿言植阶砌，净浥清露浓。","惜哉远难致，忍令伍蒿蓬。","缀词续花谱，以冠群芳丛。"]},{"t":"塞上晚眺","f":"五言律诗","c":["倒影余霞丽，晴沙入望平。","千峰含暮霭，万幕起秋声。","度垄牛羊下，归鞍雉兔盈。","割鲜将进酒，边月照高旌。"]},{"t":"雨后","f":"五言律诗","c":["凉雨晴偏好，边秋气转清。","虹从林杪断，月傍陇头生。","落叶飘含润，回沙溜有声。","仰看群雁度，寒影贴云明。"]},{"t":"扈驾幸檀柘寺恭纪","f":"七言律诗","c":["省耕郊外鸟声欢，敬从祗林拥八鸾。","法苑风飘花作雨，香溪水激石鸣湍。","含桃密缀红珠树，嫩箨新抽碧玉竿。","胜地从容驻清跸，慈云镇日护岩峦。"]},{"t":"看竹口占","f":"七言绝句","c":["林含虚籁扇清和，翠筱娟娟浥露多。","结实成阴偏得所，幸邀鸾驭数经过。"]},{"t":"御赐樱桃恭赋","f":"五言律诗","c":["朱实才春荐，宫莺啄未残。","香堪齐蜜荔，味自夺冰丸。","圆转珠千粒，轻匀露一盘。","天厨欣惠赐，绝胜驻颜丹。"]},{"t":"扈驾观麦","f":"七言律诗","c":["雨润郊原奉豫游，勤民御辇向西畴。","摇空翠浪沄沄起，覆垄黄云冉冉浮。","三白降穰占岁稔，两岐擢秀应农讴。","伫看比屋连枷动，击壤声中麦有秋。"]},{"t":"旷然尘虑清","f":"五言律诗","c":["性静涵真趣，澄观宇宙中。","未离人境外，顿觉俗情空。","有色穿帘月，无心过竹风。","一声长啸罢，俯仰浩靡穷。"]},{"t":"四时咏应制春","f":"七言律诗","c":["土融波暖遍阳春，睍睕雏莺学语频。","嘉卉满园争献笑，良苗接畛亦怀新。","韶华有意留三殿，惠泽无边及兆民。","畿甸时巡东作始，康衢忭舞颂尧仁。"]},{"t":"夏","f":"七言律诗","c":["麦黄节候届朱明，百草蕃滋万汇荣。","槛覆槐阴当午密，阶罗葵萼向阳倾。","濯枝雨过园林润，解愠风来殿阁清。","一榻桃笙临水畔，对时育物豫皇情。"]},{"t":"秋","f":"七言律诗","c":["碧天荐爽火西流，序转商飙应蓐收。","警鹤声中清露下，征鸿影外断云浮。","梧楸萧瑟宜新霁，禾黍离披庆有秋。","省敛顺时勤御跸，不耽清兴宴琼楼。"]},{"t":"冬","f":"七言律诗","c":["飘风发发迎严节，瑞雪霏霏增暮寒。","纳稼三农休蔀屋，飞葭九陛肃郊坛。","梅疏破腊开温室，竹劲凌霜挺玉栏。","敬惜岁余聆圣训，忻依内殿日承欢。"]},{"t":"癸未岁随驾南巡渡扬子江恭纪","f":"五言律诗","c":["敬从泛楼船，春江二月天。","云开孤塔迥，风送远帆联。","津柳迎清跸，沙洲接御烟。","中流回望处，翠岫列晴川。"]},{"t":"癸未中秋对月时以疾假不获扈从出塞感赋","f":"五言律诗","c":["十载中秋月，都从北塞看。","祗今临皎镜，远愧隔鸣銮。","暑退身差健，宵良意强欢。","当轩对樽酒，重念圣恩宽。"]},{"t":"皓月鉴丹宫","f":"七言律诗","c":["新秋爽气满瑶京，鸳瓦流辉一色明。","耿耿银河低紫禁，溶溶冰镜上丹楹。","素娥佩冷凌风响，金桂香飘合殿清。","但愿千秋轮不缺，团圞光彩对常盈。"]},{"t":"小园宴集","f":"五言律诗","c":["小园觞饮罢，闲步碧溪头。","岚秀秋增色，林深晚更幽。","同吟今夜月，回忆旧年游。","风景真堪赏，相携逐鹭鸥。"]},{"t":"德州晓渡","f":"七言绝句","c":["襟带燕齐此路分，舟梁晓渡马嘶群。","举鞭南指峰如黛，佳气茏葱结五云。"]},{"t":"过蒙阴","f":"五言律诗","c":["望里东蒙近，微茫草树遮。","面城峰碍日，绕郭水鸣沙。","户尽缫桑茧，人多摘茗芽。","曾闻鲁酒薄，村店一旗斜。"]},{"t":"扈跸阅河","f":"五言律诗","c":["圣主民依切，金堤玉辇临。","平成齐禹烈，底定慰尧心。","屡庆禾盈陇，勤栽柳结阴。","翕河今有颂，鼓枻入歌吟。"]},{"t":"渡扬子江","f":"七言律诗","c":["临江山势郁岧峣，江面风和絮乱飘。","锦缆解开扬子渡，龙旗飞过广陵潮。","重光丽日悬天镜，几道晴虹驾海桥。","一曲汾歌怀帝德，榜人齐唱拥兰桡。"]},{"t":"金山夜泊遇雨 其一","f":"五言律诗","c":["宿慕金山寺，今方识化城。","雨昏春嶂合，石激晚潮鸣。","不辨江天色，惟闻钟磬声。","因知羁旅境，触景易生情。"]},{"t":"金山夜泊遇雨 其二","f":"五言律诗","c":["胜地饶佳致，都教一雨收。","风掀高树吼，江叠怒涛流。","坐久云徐敛，宵深象始幽。","暂时烦虑息，我亦欲勾留。"]},{"t":"登焦山上方口占","f":"五言绝句","c":["浩浩天边水，苍苍山顶松。","老僧禅定后，隔岸一声钟。"]},{"t":"雨中泊舟枫桥遥对虎阜","f":"五言律诗","c":["维航枫桥晚，悠然见虎邱。","塔标云影直，钟度雨声幽。","僧舍当门竹，渔家隔浦舟。","茫茫吴越事，都付与东流。"]},{"t":"扈驾幸西湖","f":"七言律诗","c":["宸章璀灿丽湖轩，映带烟波羽卫屯。","山入御筵青未了，草迎跸道绿方繁。","暮巢鹤敛云间翅，远寺僧归月下门。","花柳六桥争烂熳，齐承睿日似春温。"]},{"t":"五伦图歌","f":"古风","c":["天枢位，地维张，人于其间叙伦常。","五者阙一斯不可，上自朝廷下闺房。","岂止含齿并戴发，凡有血气秉彝良。","试看翩幡众羽族，接翼引队朝凤凰。","凤凰高据碧梧俨，临御君臣礼数何煌煌！","鸣鹤在阴其子和，仙音嘹亮松风长。","夫妇唱随谐琴瑟，双飞双宿双鸳鸯。","可怜鹡鸲至翾细，往来在原集复翔。","行摇雅有急难意，同气兄弟期相将。","缅彼新莺向春柳，金梭织翠为底忙？","闻声相悦求其友，临风百啭和笙簧。","感兹群鸟义可取，从明五教敷条章。","丹青之笔此足贵，等闲花草徒芬芳。","非惟满纸绚文采，良禽指点醒顽狂。","若人立志慕忠孝，须悬此图出入瞻玩无相忘。"]},{"t":"山气日夕佳","f":"七言律诗","c":["岭衔斜照澹云收，翠霭参差晚更幽。","心静随缘皆自得，情空何事可关愁？","烟鬟碧染苍茫暮，霜叶红飞烂漫秋。","此际若逢陶隐士，更邀明月续佳游。"]},{"t":"百籁坐自吟","f":"七言律诗","c":["飒然一派起秋林，相和无人竟夕吟。","落叶萧萧声乍隐，悬泉㶁㶁响堪寻。","悠扬岂似临风笛，断续非关捣练砧。","默坐寂寥听不厌，恍于静里得空心。"]},{"t":"秋日随驾郊外驻跸遇雨","f":"七言律诗","c":["村庄驻辇省农田，共庆西成惠泽宣。","雷绕千峰明远电，雨倾四野响飞泉。","博山香爇余烟袅，龙井茶敲活火煎。","几杵钟声云外杳，顿令心地觉超然。"]},{"t":"御题松鹤图恭纪二首 其一 松","f":"七言绝句","c":["通身鳞鬣作龙文，翠色参天半入云。","天笔普垂新雨露，一株独向殿前分。"]},{"t":"御题松鹤图恭纪二首 其二 鹤","f":"七言绝句","c":["顶染丹砂缟素衣，青城何日复招归。","一时墨妙邀宸赏，千古名传丁令威。"]},{"t":"趵突泉应制","f":"七言律诗","c":["历下重临羽旆扬，名泉漾漾丽池光。","拂开玉镜涵天影，看涌银涛喷雪香。","睿藻昔曾悬日月，恩辉今又照沧浪。","温然乳液通灵脉，派引阳和浩劫长。"]},{"t":"珍珠泉应制","f":"五言律诗","c":["珍珠旧有名，官署一泓明。","似沸光靡定，无风浪自平。","流长知物润，源洁觉心清。","两度邀宸赏，澄泓荷宠荣。"]},{"t":"万寿颂三章 其一","f":"七言律诗","c":["玉殿班齐捧御筵，千官歌祝算绵延。","筹添甲子逢初度，椿纪干支庆永年。","远贡越裳重九译，来朝绛节会群仙。","更张内宴帘高卷，叠奏云韶响彻天。"]},{"t":"万寿颂三章 其二","f":"七言律诗","c":["紫禁春深丽景融，熙然身入庆云中。","瞻天有喜趋承近，祝圣无疆拜舞同。","毫覆尧眉含秀采，神凝舜目炯方瞳。","生成奇表占徵应，共指南山比寿崇。"]},{"t":"万寿颂三章 其三","f":"七言律诗","c":["南极星明耀蔚蓝，寿昌有象瑞光含。","声传中岳闻呼万，弦鼓虞廷度曲三。","日月升恒皇祚远，海河清晏圣恩覃。","捧觞戏彩春长好，岁岁惭无贡旨甘。"]},{"t":"溪水碧于草","f":"五言律诗","c":["傍涧寻花去，沿堤步翠行。","谁将芳草色，染得碧溪明。","衫縠风中绉，眉痕镜里生。","红颜云易改，可似水常清？"]},{"t":"山居自怡","f":"五言律诗","c":["生平耽静僻，每爱住深山。","百卉从荣谢，双丸任往还。","朝廷容懒慢，天地许清闲。","睡起三竿日，仙踪似可攀。"]},{"t":"今月曾经照古人","f":"七言律诗","c":["磨洗无从鉴更真，清光一片自常新。","既然此地临今夕，岂不当年照古人！","冉冉浮生成往迹，茫茫世事总飞尘。","会须直上清虚府，永向蟾宫伴桂轮。"]},{"t":"幽居","f":"七言律诗","c":["小筑幽居爱近郊，夜迟月色隐林梢。","寒侵珠箔灯光淡，风动纱窗竹影交。","野外钟声闻断续，案头诗律费推敲。","翛然兀坐情空尽，识得原无物可淆。"]},{"t":"七夕","f":"五言律诗","c":["万里碧空净，仙桥鹊驾成。","天孙犹有约，人世那无情？","弦月穿针节，花阴滴漏声。","夜凉徙倚处，河汉正盈盈。"]},{"t":"即事","f":"五言绝句","c":["晚行西郭外，策马上层冈。","暑退无多日，疏林已半黄。"]},{"t":"一日闲","f":"七言律诗","c":["闭门一日隔尘嚣，深许渊明懒折腰。","观奕偶将傍著悟，横琴只按古音调。","新情都向杯中尽，旧虑皆从枕上销。","信得浮生俱是幻，此身何处不逍遥！"]},{"t":"就正斋九日赏菊","f":"七言律诗","c":["重阳高会幔亭张，阶下寒英正吐芳。","为羡霜丛矜晚节，同来香径领秋光。","嘉宾落帽风流在，绮席征歌雅兴长。","却笑当年彭泽叟，东篱寂寞独倾觞。"]},{"t":"寒夜有怀","f":"七言律诗","c":["夜寒漏永千门静，破梦钟声渡花影。","梦醒回思记最真，那堪梦短难常亲。","兀坐谁教梦更添，起步修廊风动帘。","可怜两地隔吴越，此情惟付天边月。"]},{"t":"途次暑雨","f":"五言律诗","c":["泱漭夏云屯，滂沱塞雨繁。","绕渠沙路净，注涧石泉浑。","鹳浴依邱垤，驼鸣傍水源。","凉闺起林末，吹入小行轩。"]},{"t":"山顶船楼","f":"七言律诗","c":["楼居制仿船居好，山槛风如水槛多。","飘渺千峰翻翠浪，怒号万木吼苍波。","晴霞片片开帆影，禽鸟声声唱棹歌。","闲拄一篙云外泛，青松白石任吟哦。"]},{"t":"中元登狮子岭感怀","f":"五言律诗","c":["晚登狮子岭，四望净云烟。","叶落瘦崖树，雨过响涧泉。","人颜移岁月，秋色老山川。","令节须酬赏，天空月正圆。"]},{"t":"妙高堂","f":"七言律诗","c":["碧峰顶上结茆庐，可拟巢由物外居。","云变白衣眼底事，风翻贝叶案头书。","性天融会无今古，心月圆明彻太虚。","睡起北窗时一啸，千山答响自如如。"]},{"t":"热河闲咏七首 其一","f":"五言律诗","c":["塞北开行殿，窗临万壑松。","云封双塔岭，烟锁磬锤峰。","飘渺层峦接，盘回曲径重。","红尘难到处，何事不从容。"]},{"t":"热河闲咏七首 其二","f":"五言律诗","c":["一人临塞北，万里息边烽。","朽木含生意，闲花逞冶容。","夔魈潜隐迹，虎豹尽藏踪。","群动无纷扰，帷闻响梵钟。"]},{"t":"热河闲咏七首 其三","f":"五言律诗","c":["避冗原无意，搜奇念久灰。","境幽饶野趣，山静绝浮埃。","驯鹿时来去，闲云自往回。","长年颐养得，何畏景光催。"]},{"t":"热河闲咏七首 其四","f":"七言律诗","c":["卜居岂为避三庚，峦壑幽深气象清。","绝顶苍松多古韵，前川皓月倍常明。","薄衾坐拥浑忘我，高枕倚吟别有情。","万籁寂然银汉转，一声破梦曙钟鸣。"]},{"t":"热河闲咏七首 其五","f":"七言律诗","c":["泠泠碧涧胜丝竹，叠叠苍岩列画图。","异卉手拈陈几案，野蔬亲摘付庖厨。","闲中随展经千页，睡起新烹茶半壶。","莫谓超然解遗世，庙堂清福一慵愚。"]},{"t":"热河闲咏七首 其六","f":"七言律诗","c":["山深地僻尘嚣隔，斜荫茆堂百尺松。","石壁有斑凭雨凿，柴门无钥倩云封。","盘岩曲磴留麋迹，绕砌平沙印鹤踪。","梦觉南窗何所事，独吟独酌尽从容。"]},{"t":"热河闲咏七首 其七","f":"七言律诗","c":["闲来忘暑兼忘我，浩气冲融贯太虚。","城市山林君子宅，山林城市帝王居。","不寻仙客谈元旨，懒觅高僧讲梵书。","天地古今惟一啸，悠然自得有谁如。"]},{"t":"恭谒五台过龙泉关偶题","f":"七言律诗","c":["隔断红尘另一天，慈云常护此山巅。","雄关不阻骖鸾客，胜地偏多应迹贤。","兵象销时崇佛像，烽烟靖始扬炉烟。","治平功效无生力，赢得村翁自在眠。"]},{"t":"将至五台山月下作","f":"七言律诗","c":["深沉院落隔嚣尘，夜静高悬月一轮。","芍药栏边藏祖意，葡萄架里露天真。","契机且共论诗酒，忘我何妨互主宾。","闻说台山蓦直路，明朝不必问前津。"]},{"t":"仲秋有怀","f":"七言律诗","c":["翻飞庭院叶初干，怅怏难禁独倚栏。","两地西风人梦隔，一天凉雨雁声寒。","惊秋剪烛吟新句，把酒论文忆旧欢。","辜负此时曾有约，桂花香好不同看。"]},{"t":"秋夜直院","f":"七言律诗","c":["碧落沉沉蜡炬寒，清秋直院夜将残。","金吾禁肃千门静，玉漏声稀列宿阑。","宫树半笼蟾影澹，天街欲湿露华漙。","垂帘兀坐心如水，此际凭谁举话端？"]},{"t":"长至日","f":"五言律诗","c":["候琯灰初动，曈昽旭日临。","晴光金阙迥，佳气帝城深。","子建三微首，功添一线阴。","静观消长理，不息见天心。"]},{"t":"梅花二首 其一","f":"七言律诗","c":["冰蕊舒芬腊欲残，香魂脉脉自凌寒。","先春不借东皇力，冒雪惟容隐士看。","素面浓嫌梨粉艳，仙标狂鄙柳绵干。","玲珑铁干珠光映，宛若疏星傍晓阑。"]},{"t":"梅花二首 其二","f":"七言律诗","c":["开迟宁逐雪消残，岁底曾经彻骨寒。","未识芳心何处托，欲将冷眼向谁看？","饮余含笑香微吐，暖入凝酥晕不干。","一种天然清意味，每牵幽赏到更阑。"]},{"t":"松","f":"五言律诗","c":["矫矫拂云姿，能教众木卑。","苍鳞疑挟雨，翠鬣静含飔。","花暖飘香粉，膏流结紫芝。","千龄待黄鹤，集此最高枝。"]},{"t":"竹","f":"五言律诗","c":["绿染竿竿润，青笼个个阴。","节高寒愈劲，气洁暑难侵。","密雨惊龙起，清风引凤吟。","幸邀君子号，为尔解虚心。"]},{"t":"梅","f":"五言律诗","c":["瘦影亭亭立，幽香细细清。","竹希霜后操，松订岁寒盟。","先得东风意，犹含太古情。","超然群卉外，一味澹为生。"]},{"t":"元旦","f":"七言律诗","c":["辉辉灯火曙光连，气淑风条景物鲜。","双阙禁钟鸣朔旦，千门春贴迓芳年。","金花杂组新裁胜，柏叶清樽喜侍筵。","仰戴圣皇康且寿，长期元节沐恩偏。"]},{"t":"春日闲行","f":"七言律诗","c":["清旭笼云暖气含，远山如黛水如蓝。","啼鸠到处青桑垄，乳鸭谁家碧柳潭。","公子醉鞭金勒骑，佳人笑摘野花簪。","春光骀荡东风缓，蜂蝶悠扬晚更憨。"]},{"t":"园居二首 其一","f":"五言律诗","c":["晴晖荡林翠，芳岫映春漪。","燕怯飞还歇，鸥驯信可期。","异书探古字，真迹辨藏碑。","晚更携兰棹，溯洄月上迟。"]},{"t":"园居二首 其二","f":"五言律诗","c":["懒问浮沉事，闲娱花柳朝。","吴儿调凤曲，越女按鸾箫。","道许山僧访，棋将野叟招。","漆园非所慕，适志即逍遥。"]},{"t":"风","f":"七言律诗","c":["綄影悠扬五两轻，少男应律蛰虫惊。","破萌拆甲全无迹，拂幔开楹若有情。","草偃方将行夏令，条鸣切莫变秋声。","松涛竹籁俱堪赏，雪后飘梅韵更清。"]},{"t":"花","f":"七言律诗","c":["深浅秾纤万种姿，爱花自古有情痴。","书窗艳入红牙管，妆镜娇添绿鬓丝。","韦曲千芳初放日，洛阳群卉正当时。","若将解语朱颜比，争似长年锦满枝。"]},{"t":"雪","f":"七言律诗","c":["谁把冰绡细剪裁，絮飘轩槛粉铺苔。","千山种遍峰峰玉，九陌开齐树树梅。","鹤氅离披驴背咏，渔蓑冷淡鸭头回。","骖鸾拟赴瑶池宴，飞舞琼花入酒杯。"]},{"t":"月","f":"七言律诗","c":["体空质妙禀阳辉，一镜明能遍九围。","冷伴画楼吹玉笛，清临香阁理金徽。","纤纤柳外星光隐，寂寂花间烛影微。","独有沧江烟浪里，扁舟载得满轮归。"]},{"t":"池边","f":"五言律诗","c":["斋居读书暇，晚向池边步。","水面落花浮，水底行云度。","山色从西来，泉声日东注。","静观物何闲，超然得妙悟。"]},{"t":"花前","f":"七言律诗","c":["小园目眩揽群芳，红紫成帷锦绣张。","次第迎风争献笑，参差向日各分香。","无名也自矜韶节，入品方堪逞艳阳。","抱蕊攒英蜂与蝶，何曾解得惜春光。"]},{"t":"清凉纪游一十四首 其二 东台","f":"七言律诗","c":["嵯峨东陟插云峰，壁翠峦苍亘百重。","妙吉祥师常说法，那罗延窟惯藏龙。","远窥沧海初升日，响振空林欲曙钟。","一派明霞光绚烂，天然佛镜豁心胸。"]},{"t":"清凉纪游一十四首 其三 南台","f":"七言律诗","c":["岿然秀拔峙南台，顶势穹窿若覆杯。","香阁遥瞻烟锁处，宝灯闻说夜飞来。","仙岩铺锦凭谁绣，虎窟屯云为我开。","欲礼真容先在望，频催前骑蹑崔嵬。"]},{"t":"清凉纪游一十四首 其四 西台","f":"七言律诗","c":["挂月岩前一经探，岧峣紫翠叠烟岚。","圆机风与溪相答，秘义人同石共谭。","灵异迹多难罄笔，清凉峰好尽如簪。","无边觉海毫端入，八水源头不用参。"]},{"t":"清凉纪游一十四首 其五 北台","f":"七言律诗","c":["北台秀矗斗杓傍，楼殿凌虚结上方。","众壑俱从檐下落，万缘都向槛边忘。","洪河如带明分野，恒岳为邻接大荒。","世界三千空色喻，岂离般若一毫光。"]},{"t":"清凉纪游一十四首 其六 中台","f":"七言律诗","c":["五朵青莲簇翠鬟，峨峨一朵涌中间。","近来若个宗风彻，至此方知佛日闲。","采菊梵仙归洞去，踏花狮子自空还。","法身宝塔门门现，毕竟游人未到山。"]},{"t":"清凉纪游一十四首 其七 真容院","f":"五言律诗","c":["殊像原无二，庄严属画工。","昔闻叱牛叟，今见跨狮翁。","月面光莹玉，珍缨贯慧风。","真容从未隐，漫道现虚空。"]},{"t":"清凉纪游一十四首 清凉石二首之一 其八","f":"七言绝句","c":["光寒如镜卧深云，半是云斑半藓纹。","谁识方方一片里，古今容尽屐交纷。"]},{"t":"清凉纪游一十四首 清凉石二首之二 其九","f":"七言绝句","c":["体本清凉自解烦，天然秀色蓄云根。","曼殊说法今何在，参客空寻趺坐痕。"]},{"t":"清凉纪游一十四首 其十 过清凉山诸寺","f":"七言律诗","c":["祗林几处隐松关，门带寒溪碧玉湾。","历叩花宫寻白足，遍登香阁看青山。","无尘觉地猿能定，不系神心云共闲。","一片清凉苍翠色，家家分得满窗间。"]},{"t":"清凉纪游一十四首 出山途中口占二首之一 其十一","f":"七言绝句","c":["路转层台树几重，绿阴如幄护金容。","行从琪草瑶花过，衣染生香百和浓。"]},{"t":"清凉纪游一十四首 出山途中口占二首之二 其十二","f":"七言绝句","c":["日射关门宿雾开，化城咫尺首重回。","仙云片片随行骑，直自清凉山顶来。"]},{"t":"清凉纪游一十四首 其十三 射虎川台麓寺","f":"七言律诗","c":["精蓝郁起碧岩幽，此日斋诚驻紫骝。","东指凤城双阙迥，西瞻鹫岭半空浮。","梵钟缥缈香云外，宝翰昭回古殿头。","神表天弧开净域，河沙浩劫颂宸游。"]},{"t":"清凉纪游一十四首 其十四 再度龙泉关","f":"五言律诗","c":["遨游从净土，安稳度香城。","鸟亦通禅悦，松如响梵声。","山岚朝夕幻，关柳去来迎。","凤阙慈云近，惟殷问寝情。"]},{"t":"热河道中","f":"七言律诗","c":["山色岚光映马鞯，软沙细草缓鸣鞭。","花开遍野时飞蝶，云散晴空好射鸢。","孤店酒帘飘柳外，几家溪水绕门前。","穿林暮返携锄叟，略彴欹斜度晚烟。"]},{"t":"湖亭观荷","f":"七言律诗","c":["馆字清幽晓气凉，更宜澹荡对烟光。","湖平水色涵天色，风过荷香带叶香。","戏游金鳞依密荇，低飞银练贴芳塘。","兰桡折取怜双蒂，殊胜陈隋巧样妆。"]},{"t":"河灯","f":"五言律诗","c":["月涌湖心白，灯燃湖面红。","琪花开色界，电彩灿虚空。","棹泛明河里，人游列宿中。","兰舠鸣梵呗，飘入藕花风。"]},{"t":"田家四时词春","f":"古风","c":["陌头杨柳初放，溪上桃花欲燃。","处处青鸠呼雨，家家黄犊耕烟。","牧童群嬉挑菜，饷妇自解撑船。","借问浪游城市，何如乐业村田！"]},{"t":"夏","f":"古风","c":["带露叶盈蚕箔，翻云麦熟田家。","白水千塍秧马，绿阴几户缫车。","日午鸣蝉远近，风薰飞燕横斜。","男女适均劳逸，相逢只说桑麻。"]},{"t":"秋","f":"古风","c":["风露微凉天气，四乡一派秋光。","荞吐东阡雪白，禾香南亩云黄。","青刈园蔬足雨，红收林实经霜。","举室欣逢乐岁，商量筑圃登场。"]},{"t":"冬","f":"古风","c":["霭霭炊烟茆舍，霏霏腊雪柴门。","阑静闲眠羔犊，篱牢安稳鸡豚。","夜织梭鸣哑轧，朝舂杵韵喧繁。","赛社争挝祭鼓，歌呼新酿盈盆。"]},{"t":"亭上","f":"五言律诗","c":["幽亭临玉沼，芳草带金塘。","石叠玲珑巧，花飘荏苒香。","油云翻湿影，丝雨溅虚凉。","倚槛纡流览，天容荡水光。"]},{"t":"闰中秋","f":"七言律诗","c":["一年最是中秋好，八月欣逢两度过。","彩耀桂轮前夕满，凉生玉露此时多。","入帘喜若重来客，照席欢宜续旧歌。","自笑闲情谁得似，漏深更恋赏金波。"]},{"t":"大觉寺","f":"五言律诗","c":["翠微尘外境，峰壑画图成。","寺向云边出，人从树杪行。","香台喧鸟语，禅室绕泉鸣。","日午松阴转，钟传说偈声。"]},{"t":"月夜泛舟","f":"七言律诗","c":["堤柳阴分举画桡，数声呕轧荡轻舠。","芙蓉馆北香浮沼，桑柘村西月满桥。","雪鸟冲烟孤鹭起，金鳞破浪巨鱼跳。","溯洄一片清光里，心会南华秋水谣。"]},{"t":"秋夕","f":"五言律诗","c":["初月明楼角，微风动树条。","夜凉虫语细，秋老雁声骄。","息虑征神爽，忘怀觉境超。","阴阴深竹里，时见一萤飘。"]},{"t":"九日","f":"五言律诗","c":["九日秋容老，山山晴色宜。","紫萸香可佩，黄菊艳当时。","屐为登高著，尊因选胜移。","愿言多载酒，拂石醉题诗。"]},{"t":"黑龙潭","f":"五言律诗","c":["平麓蟠崇阜，云潭结涧阿。","镜光涵铁冷，溜响喷珠多。","秘识龙藏穴，深疑蜃蜕窝。","农田望霖雨，于此乞恩波。"]},{"t":"拟渔樵耕牧四首 其一 渔","f":"七言律诗","c":["舴艋漂摇随处家，一篙绿水度年华。","风罾逐浪蘋溪远，雨网冲烟柳渚斜。","在在耽闲盟白鹭，朝朝买醉馔红虾。","团圞儿女欢篷底，岂羡浮名举世夸。"]},{"t":"拟渔樵耕牧四首 其二 樵","f":"七言律诗","c":["一生踪迹在烟霞，不植条桑不种麻。","翠柏斫来青带叶，古藤担去紫垂花。","歌长时引猿窥穴，归晚常乘月到家。","笔指云山为活计，那须卮酒祝篝车。"]},{"t":"拟渔樵耕牧四首 其三 耕","f":"七言律诗","c":["茅屋疏篱翠蔓牵，绕篱桑拓翳平田。","村中斑白闲无事，垄上青黄喜有年。","比户机梭鸣月下，一家儿女聚灯前。","那能更羡公侯贵，蟹美鱼肥稻熟天。"]},{"t":"拟渔樵耕牧四首 其四 牧","f":"七言律诗","c":["平原浅草澹烟和，指点牛羊下绿坡。","逐队饮时泉响细，偷闲卧处柳阴多。","长河曲岸悠扬笛，斜日微风断续歌。","借问道傍骑马客，何如犊背稳披蓑。"]},{"t":"四花词桃花","f":"七言绝句","c":["玉洞仙葩绛露滋，纤浓早占仲春时。","群芳夺色朝霞艳，向日先开第一枝。"]},{"t":"荷花","f":"七言绝句","c":["绿蒂红衣薄醉妆，凌波舒影覆鸳鸯。","莲房有子心偏苦，藕节含香丝更长。"]},{"t":"桂花","f":"七言绝句","c":["月殿珠英绽嫩黄，婆娑翠叶隐微霜。","为含贞性能长洁，独向秋风压众芳。"]},{"t":"梅花","f":"七言绝句","c":["绰约琼姿澹自真，清标冒雪倍精神。","不同群卉争妖艳，一种寒香最可人。"]},{"t":"元夕过僧寺","f":"七言律诗","c":["步入东林月满坛，逶迤曲径绕平栏。","禅心清净尘心远，灯影幽微幡影寒。","香煮玉泉分茗椀，静依宝筏坐蒲团。","庙堂不系偷闲客，得向宗门举话端。"]},{"t":"初春郊行","f":"七言律诗","c":["土膏开动草芬芳，缓辔循行十里塘。","细雨斜飘山渐绿，小桃半吐柳初黄。","闲随戏水沙鸥狎，又见营巢海燕忙。","寓目物情忻自得，良辰倍觉惜韶光。"]},{"t":"临轩寓目","f":"七言律诗","c":["绮窗罢抚紫琼琴，香烬金炉鹤梦沉。","多事草偏名醒醉，可人花解结同心。","风翻曲沼千层碧，云过重檐一霎阴。","栏外有情双蛱蝶，翩翩飞入海棠深。"]},{"t":"三春景物滋","f":"七言律诗","c":["阳春百物向荣时，况复郊原雨露滋。","黍绿禾青麻翳垄，桃红李白杏交枝。","游蜂舞蝶纷纷戏，乳燕鸣鸠处处宜。","幸际圣皇熙皞世，佳辰若负便为痴。"]},{"t":"睡起","f":"七言律诗","c":["小斋岑寂漏声迟，书卷香炉得自怡。","花不识愁工巧笑，柳恒如醉类情痴。","梦回窗隙风翻帙，光动帘钩月映池。","静里陶然清兴剧，苔笺石墨坐题诗。"]},{"t":"柳絮","f":"七言律诗","c":["楝花风过雪霏霏，万点沾衣不湿衣。","轻逐东西香毂转，狂随来去马蹄飞。","河桥漠漠迷渔艇，村店纷纷扑酒旂。","巧入疏帘如有意，拂琴飘卷伴书帏。"]},{"t":"春深闲居","f":"五言律诗","c":["长日惬幽栖，轩窗面小溪。","云开徐自敛，鸟歇又重啼。","爱水频垂钓，看花偶一题。","坐怜春已暮，望里绿阴齐。"]},{"t":"咏牡丹","f":"七言律诗","c":["酣艳枝枝五色妆，难将兰麝与论量。","欲留春住舒奇彩，独擅娇多领众芳。","天女霞冠簪宝髻，仙姝玉佩曳霓裳。","琼浆饮罢瑶池宴，双颊潮红腻粉光。"]},{"t":"新绿","f":"五言律诗","c":["昨树花多叶，今看叶胜花。","翠含新色嫩，绿重午阴斜。","霁景鸣乾鹊，烟光乱乳鸦。","最宜初夏候，掩映碧窗纱。"]},{"t":"寓目","f":"五言律诗","c":["漠漠云元际，茸茸草渐齐。","花繁从径窄，溪涨觉桥低。","捎堞巢梁燕，衔鱼没浪鹈。","偶来松下坐，斜倚看浇畦。"]},{"t":"咏榴花","f":"七言律诗","c":["春芳零落绛英佳，独茂薰风正色谐。","翠叶布阴新绿染，蕊珠吐艳密红排。","石家击碎珊瑚树，赵燕攒成玛瑙钗。","好是一花生百子，中含琼液笑当阶。"]},{"t":"午日","f":"七言律诗","c":["绿菖青艾绛纱囊，菰叶堆盘解粽香。","竞渡楚人传故事，卖符道士弄灵章。","葵心向日擎枝丽，榴火烧云并蒂芳。","拂拂薰风初试葛，华轩挥扇引蒲觞。"]},{"t":"池上待月","f":"五言律诗","c":["水含夕籁静，余亦澹怀空。","星彩低穿树，花香暗度风。","初看幽径白，渐露小桥红。","行到天心处，清光更不同。"]},{"t":"雨后园亭即景","f":"七言律诗","c":["玉溪宛转云流镜，翠巘参差黛扫屏。","堤树风翻深浅叶，径苔雨染淡浓青。","鸣琴遥和岩头瀑，凉箔齐钩水面亭。","最是夜初群籁寂，临轩坐拥一湖星。"]},{"t":"荷花","f":"五言律诗","c":["袅袅摇波碧，亭亭映日红。","芳能消暑气，秀独占薰风。","叶翠遮尘盖，茎香劝酒筒。","仙姿时一挹，清洁与心通。"]},{"t":"夏日楼前","f":"七言律诗","c":["柳布浓阴覆钓矶，楼前翠嶂绿成围。","骤过白雨长虹见，点破青天一鸟飞。","闲处方知尘事扰，静中始悟道机微。","不烦驱暑摇团扇，水面风生透葛衣。"]},{"t":"七夕","f":"七言律诗","c":["沉李浮瓜乞巧筵，银河今夜渡仙軿。","鸳鸯楼看霞成锦，翡翠屏开月上弦。","滴露梧桐秋影薄，凌波菡萏晚香鲜。","彩盘针线年年事，一瞬欢期万劫缘。"]},{"t":"再过大觉寺","f":"七言律诗","c":["一径烟萝夕照深，山窗幽竹更添阴。","老僧谭法挥松麈，异鸟衔花敛雪襟。","阁响钟声传密义，潭空云影鉴禅心。","频来端爱风泉洁，却向无弦听好音。"]},{"t":"喜晴","f":"五言律诗","c":["阴翳看销尽，晴光喜满扃。","云归天湛碧，雨过树余青。","痴蝶深藏蕊，游鱼戏逐萍。","无尘怜净几，偶一阅金经。"]},{"t":"秋夕泛舟","f":"七言律诗","c":["芙蓉吐艳漙清露，杨柳垂条曳晚烟。","几点凫鹥惊画桨，一湖风月载兰船。","枣悬硕果心皆赤，芡劈香包实本圆。","揽得秋光游兴剧，清宵景物倍鲜妍。"]},{"t":"中秋","f":"七言律诗","c":["云敛星疏净碧穹，月圆今夕正秋中。","十分明照三垣彻，一片光含万象同。","樽泛金波凉滟滟，花浮玉露湿濛濛。","恍疑夜半闻仙乐，满院香飘桂子风。"]},{"t":"园景十二咏 其一 深柳读书堂","f":"五言律诗","c":["郁郁千株柳，阴阴覆草堂。","飘丝拂砚石，飞絮点琴床。","莺啭春枝暖，蝉鸣秋叶凉。","夜来窗月影，掩映简编香。"]},{"t":"园景十二咏 其二 竹子院","f":"五言律诗","c":["深院溪流转，回廊竹径通。","珊珊鸣碎玉，袅袅弄清风。","香气侵书帙，凉阴护绮栊。","便娟苍秀色，偏茂岁寒中。"]},{"t":"园景十二咏 其三 梧桐院","f":"五言律诗","c":["棹泛湾湾水，桥通院院门。","吟风过翠屋，待月坐桐轩。","秋叶催诗落，春花应节繁。","只应金井畔，好借凤凰鶱。"]},{"t":"园景十二咏 其四 葡萄院","f":"五言律诗","c":["纡回深树里，一水暗通舟。","乳汁香兼润，冰丸滑欲流。","阴铺青叶护，架络翠藤稠。","西域传奇种，园丁献早秋。"]},{"t":"园景十二咏 其五 桃花坞","f":"五言律诗","c":["水南通曲港，水北入回溪。","绛雪侵衣艳，赪霞绕屋低。","影迷栖栋燕，声杳隔林鸡。","槛外风微起，飘零锦堕泥。"]},{"t":"园景十二咏 其六 耕织轩","f":"五言律诗","c":["轩亭开面面，原隰对畇畇。","禾稼迎窗绿，桑麻窸地新。","檐星窥织火，渠水界田畛。","辛苦农蚕事，歌诗可系豳。"]},{"t":"园景十二咏 其七 菜圃","f":"五言律诗","c":["凿地新开圃，因川曲引泉。","碧畦一雨过，青壤百蔬妍。","洁爱沾晨露，鲜宜润晚烟。","倚亭闲伫览，生意用忻然。"]},{"t":"园景十二咏 其八 牡丹台","f":"五言律诗","c":["叠云层石秀，曲水绕台斜。","天下无双品，人间第一花。","艳宜金谷赏，名重洛阳夸。","国色谁堪并，仙裳锦作霞。"]},{"t":"园景十二咏 其九 金鱼池","f":"五言律诗","c":["甃地成卐字，注水蓄文鱼。","藻映十分翠，栏围四面虚。","泳游溪涨后，泼剌月明初。","物性悠然适，临观意亦舒。"]},{"t":"园景十二咏 其十 壶中天","f":"五言律诗","c":["峰峻疑无路，云深却有扉。","鹤闲时独唳，花静不轻飞。","洞里春长驻，壶中月更辉。","一潭空似镜，碧色动帘衣。"]},{"t":"园景十二咏 其十一 涧阁","f":"五言律诗","c":["平桥依麓转，一带接垂杨。","阁峻横云影，栏虚漾水光。","度香花外厦，挹翠树西廊。","倚槛看飞鸟，披襟引兴长。"]},{"t":"园景十二咏 其十二 莲花池","f":"五言律诗","c":["云锦漙新露，纷披映柳塘。","浅深分照水，馥郁共飘香。","姿美天然洁，波清分外凉。","折花休采叶，留使荫鸳鸯。"]},{"t":"扈从水围观猎","f":"五言律诗","c":["河冰初泮候，凫雁集春湾。","号令明搜猎，威仪肃圣颜。","禽从星箭落，恩自御舟颁。","围罢皇情豫，欢腾鹓鹭班。"]},{"t":"秋狝扈驾","f":"五言律诗","c":["玉帐秋风劲，朱旗霜野开。","千屯瞻凤葆，万骑待龙媒。","犬疾追狐窜，弓鸣逐鹿回。","天颜微一笑，欢动震如雷。"]},{"t":"侍驾景山观杀虎","f":"五言律诗","c":["山拥黄扉壮，林开碧殿隈。","雄风生虎腋，腥雾袭龙衣。","血浅雕戈劲，弧张利爪摧。","桓桓争奏技，敛手有余威。"]},{"t":"汤泉","f":"七言律诗","c":["凌云兰殿郁崔嵬，绕槛涟漪温液回。","养正为能恒净洁，莹心不止荡氛埃。","宿含炎德珠光润，只觉阳和涧底来。","著绩岂徒堪愈疾，溶溶一脉万年开。"]},{"t":"上元","f":"五言律诗","c":["玉宇沉沉夜，花阴皓魄升。","画栏凝瑞霭，绮席上春灯。","笛引歌声叠，衣翻舞袖层。","任教莲漏促，莫负酒如渑。"]},{"t":"清明","f":"七言律诗","c":["春云蔼蔼罨重城，二月天容逗嫩晴。","雪尽柳条青可折，寒消桃蕊绛初成。","谁家新燕低飞影，何处归鸿晚度声。","窗外好风樽内酒，钻榆取火又清明。"]},{"t":"春日","f":"七言律诗","c":["独有东风擅剪裁，朱朱白白后先开。","鸟因枝密潜身隐，蝶为香多作队来。","紫陌笙歌喧陆海，青郊车马动春雷。","更攲晓枕寻残梦，何事林鸠故故催。"]},{"t":"初夏扈跸热河","f":"五言律诗","c":["行苑留仙跸，层峦俨赤城。","烟光浓树色，暑气散泉声。","地僻花偏艳，山深梦亦清。","瞻依忻圣豫，风物慰皇情。"]},{"t":"狮子园夏日","f":"七言律诗","c":["石屋荆扉枕翠岗，烟峦朝夕郁丹苍。","棋敲绿树阴中局，酒泛红薇架下觞。","珠箔昼摇新竹影，玉池晚送嫩荷香。","居闲漫谓全无事，一榻临风蝶梦长。"]},{"t":"山亭","f":"七言律诗","c":["茑萝满树带烟垂，筛月梳风作幔帏。","流水似琴还似筑，青山宜画又宜诗。","饥鼯窃果缘枝捷，乳雉呼群出草迟。","独倚石栏舒远目，亭前幽谷起云时。"]},{"t":"画栏","f":"七言律诗","c":["薰风披拂画栏东，照眼榴花烂熳红。","暑气不侵松阁内，清阴长在竹窗中。","由来丘壑情堪寄，即此蓬瀛路可通。","次第药阶香晚露，纤纤新月上梧桐。"]},{"t":"美人把镜图四首 其一","f":"七言绝句","c":["手摘寒梅槛畔枝，新香细蕊上簪迟。","翠鬟梳就频临镜，只觉红颜减旧时。"]},{"t":"美人把镜图四首 其二","f":"七言绝句","c":["晓妆髻插碧瑶簪，多少情怀倩竹吟。","风调每怜谁解会，分明对面有知心。"]},{"t":"美人把镜图四首 其三","f":"七言绝句","c":["竹风飒飒振琅籼，玉骨棱棱耐峭寒。","把镜几回频拂拭，爱他长共月团栾。"]},{"t":"美人把镜图四首 其四","f":"七言绝句","c":["晓寒庭院闭苍苔，妆镜无聊倚玉台。","怪底春山螺浅淡，画眉人尚未归来。"]},{"t":"美人展书图二首 其一","f":"七言绝句","c":["丹唇皓齿瘦腰肢，斜倚筠笼睡起时。","毕竟痴情消不去，缃编欲展又凝思。"]},{"t":"美人展书图二首 其二","f":"七言绝句","c":["小院莺花正感人，东风吹软细腰身。","抛书欲起娇无力，半是怜春半恼春。"]},{"t":"耕图二十三首 其一 浸种","f":"五言律诗","c":["百谷遗嘉种，先农著懋功。","春暄二月后，香浸一溪中。","重穋随宜辨，筠笼用力同。","每多贤父老，占节识年丰。"]},{"t":"耕图二十三首 其二 耕","f":"五言律诗","c":["原隰韶光媚，茅茨暖气舒。","青鸠呼雨急，黄犊驾犁初。","畎亩人无逸，耕耘事敢疏！","勤劬课东作，扶策历村墟。"]},{"t":"耕图二十三首 其三 耙耨","f":"五言律诗","c":["农务时方急，春潮堰欲平。","烟笼高柳暗，风逐去鸥轻。","压笠低云影，鸣蓑乱雨声。","耙头船共稳，斜立叱牛行。"]},{"t":"耕图二十三首 其四 耖","f":"五言律诗","c":["南亩耕初罢，西畴耖复亲。","四蹄听活活，十顷望畇畇。","蝶舞黄萱晚，莺归绿树新。","春光长不负，只有力田人。"]},{"t":"耕图二十三首 其五 碌碡","f":"五言律诗","c":["如轮转机石，历碌向东皋。","驱犊亦何急，平田敢告劳。","春塍萦似滞，沃壤腻于膏。","水族堪供饷，倾樽醉蟹螯。"]},{"t":"耕图二十三首 其六 布秧","f":"五言律诗","c":["种包忻拆甲，岸畔竞携筐。","活活冲泥布，纷纷落垄香。","追随欢幼稚，祝祷愿丰穰。","气候今年早，行看剌水秧。"]},{"t":"耕图二十三首 其七 初秧","f":"五言律诗","c":["珍惜占城种，携儿上垄来。","一溪添雨足，盈亩喜秧开。","宿露浓相浥，韶阳暖复催。","忻忻频笑指，转眼可移栽。"]},{"t":"耕图二十三首 其八 淤荫","f":"五言律诗","c":["鸟鸣村陌静，春涨野桥低。","已爱新秧好，旋看覆垄齐。","淤时争早作，课罢岂安栖。","沾体兼涂足，忙忙日又西。"]},{"t":"耕图二十三首 其九 拔秧","f":"五言律诗","c":["吉辰逢社后，比户趁忙时。","盈把分青壤，和根灌绿漪。","儿童担饷榼，妇子制秧旗。","惯得为农乐，辛劳自不知。"]},{"t":"耕图二十三首 其十 插秧","f":"五言律诗","c":["令序当芒种，农家插莳天。","倏分行整整，停看影芊芊。","力合闻歌发，栽齐听鼓前。","一朝千顷遍，长日正如年。"]},{"t":"耕图二十三首 其十一 一耘","f":"五言律诗","c":["饱雨纤纤长，含风叶叶柔。","载芟除宿莠，挹注引新流。","阴借临溪树，声传隔陇讴。","炊烟村畔起，归路缓驱牛。"]},{"t":"耕图二十三首 其十二 二耘","f":"五言律诗","c":["郁郁平畴绿，劳劳一载耘。","理苗疏是法，非种去宜勤。","笠重初收雾，锄轻半带云。","日高忙饷妇，稚子故牵裙。"]},{"t":"耕图二十三首 其十三 三耘","f":"五言律诗","c":["锄莠日当午，骄阳若火燔。","耘耔须尽力，辛苦只今番。","蝉噪风前急，蛙声水底喧。","酿花宜郁暑，翠浪舞翩翻。"]},{"t":"耕图二十三首 其十四 溉灌","f":"五言律诗","c":["艺夺天工巧，人勤地力加。","桔槔声振鼓，戽斗疾翻车。","灌注畦旋满，呕哑日欲斜。","况兼风露美，篟篟吐新华。"]},{"t":"耕图二十三首 其十五 收刈","f":"五言律诗","c":["西成已在望，早作更呼欢。","刈穗香生把，盈筐露未干。","啄遗鸦欲下，拾滞稚争欢。","主伯欣相庆，丰年俯仰宽。"]},{"t":"耕图二十三首 其十六 登场","f":"五言律诗","c":["红籼收十月，白水浸陂塍。","酿熟田家庆，场新岁事登。","云堆香冉冉，露积势层层。","劳瘁三时过，饔飧幸可凭。"]},{"t":"耕图二十三首 其十七 持穗","f":"五言律诗","c":["力田欣有岁，晒稻喜晴冬。","响落连耞急，尘浮夕照浓。","鼠衔犹畏懦，鸡啄自从容。","幸值丰亨世，尧民比屋封。"]},{"t":"耕图二十三首 其十八 舂碓","f":"五言律诗","c":["野陌霜风早，柴门晚日多。","舂声接邻响，杵韵洽豳歌。","颗颗珠倾篚，莹莹雪满箩。","为怜艰苦得，把握屡摩挲。"]},{"t":"耕图二十三首 其十九 筛","f":"五言律诗","c":["治粒频求洁，田家亦苦心。","筛风当户北，避日就檐阴。","一饱功非易，终年力不禁。","君看圆似玉，我爱胜如金。"]},{"t":"耕图二十三首 其二十 簸扬","f":"五言律诗","c":["朝来风色好，箕宿应维南。","敢惜翻飞力，宁教糠秕参。","干圆输县吏，狼藉戒童男。","得免催租负，方无俯仰惭。"]},{"t":"耕图二十三首 其二十一 砻","f":"五言律诗","c":["地结霜痕白，檐虚夜气青。","声殷砻早谷，风动闭寒扃。","玉色鲜堪比，珠光泻不停。","蒸炊谋室妇，农祖荐朝馨。"]},{"t":"耕图二十三首 其二十二 入仓","f":"五言律诗","c":["勤劳临岁暮，入囷及良朝。","墉栉宁奢望，储藏幸已饶。","赋完农有暇，门静吏无嚣。","苫廪牢封固，无虞雨雪飘。"]},{"t":"耕图二十三首 其二十三 祭神","f":"五言律诗","c":["雨旸征帝德，丰稔慰氓愚。","赛鼓村迎社，神灯夜祷巫。","酒浆泻罂盎，肴核献盘盂。","敢乞长年惠，穰穰遂所需。"]},{"t":"织图二十三首 其一 浴蚕","f":"五言律诗","c":["门多杨柳风，溪涨桃花水。","村酒酝羊羔，春闺浴蚕子。","纤纤弄翠盆，戢戢蠕香纸。","雪茧与冰丝，妇功从此始。"]},{"t":"织图二十三首 其二 二眠","f":"五言律诗","c":["百舌鸟初鸣，再眠蚕在箔。","陌桑青已柔，堤草绿犹弱。","正宜旭日和，惟恐春寒作。","妇忙儿不知，枣栗频啼索。"]},{"t":"织图二十三首 其三 三眠","f":"五言律诗","c":["春见拂帘栊，春露繁桑柘。","绕箔理三眠，烧灯绕五夜。","大姑席未安，小姑梳弗暇。","喔喔唱邻鸡，提筐邀比舍。"]},{"t":"织图二十三首 其四 大起","f":"五言律诗","c":["今春寒暖匀，南陌条桑好。","箔上叶忧稀，枝头采戒早。","不知春几多，但觉蚕欲老。","阿谁红粉妆，寻芳踏堤草。"]},{"t":"织图二十三首 其五 捉绩","f":"五言律诗","c":["生熟乃有时，老嫩莫纷糅。","恐烦姑与嫜，服劳夜继昼。","松火发瓦盆，星芒射阶溜。","次第了架头，匆忙顾童幼。"]},{"t":"织图二十三首 其六 分箔","f":"五言律诗","c":["新燕掠风轻，新蚕偕日长。","分箔天气暄，食叶雨声响。","少妇采林间，倦归歇陌上。","门前桑骚骚，黄云接青壤。"]},{"t":"织图二十三首 其七 采桑","f":"五言律诗","c":["清和天气佳，比户采桑急。","瀼瀼零露繁，冉冉绿阴湿。","高柯学猱升，落葚教儿拾。","昨摘满笼归，姑犹嗔不给！"]},{"t":"织图二十三首 其八 上簇","f":"五言律诗","c":["东邻催早耕，西舍呼浸谷。","花残蜀鸟啼，春老吴蚕熟。","蚑蚑鞠雪腰，盈盈皤丝腹。","剪草架初齐，女郎看上簇。"]},{"t":"织图二十三首 其九 炙箔","f":"五言律诗","c":["温扇花信风，寒酝麦秋雨。","葭帘张蟹舍，松盆暖蚕户。","香生雪茧明，光吐银丝缕。","门忌少人踪，语燕喧衡宇。"]},{"t":"织图二十三首 其十 下簇","f":"五言律诗","c":["前月浴新蚕，今月摘新茧。","浴蚕柳叶纤，摘茧柳绵卷。","膏沐曾未施，风光觉潜转。","邻曲慰劳来，欢情一共展。"]},{"t":"织图二十三首 其十一 择茧","f":"五言律诗","c":["倾筐香雪明，择茧檐日上。","大半作丝纶，三分充绵纩。","嘱妪理从容，择惯知瘠壮。","所虑梅雨过，插秧趁溪涨。"]},{"t":"织图二十三首 其十二 窖茧","f":"五言律诗","c":["挽袖解长裙，香汗湿红颊。","农事委良人，蚕功独在妾。","层层下簇完，劳劳窖茧接。","作苦感天公，冰雪满箱箧。"]},{"t":"织图二十三首 其十三 练丝","f":"五言律诗","c":["烟流矮屋青，水汲前溪洁。","掉车若卷风，映釜如翻雪。","丝头入手长，左右旋转忙。","轧轧听交响，行人闻茧香。"]},{"t":"织图二十三首 其十四 蚕蛾","f":"五言律诗","c":["邻始通往来，暂时解忙促。","出茧影翩翩，翅光腻粉沃。","秧苗已抽青，桑叶再见绿。","送蛾须水边，流传笑农俗。"]},{"t":"织图二十三首 其十五 祀神","f":"五言律诗","c":["丰祀报先蚕，洒庭伫来格。","酾酒注樽罍，献丝当圭璧。","堂下趋妻孥，堂上拜主伯。","神惠乞来年，盈箱赐倍获。"]},{"t":"织图二十三首 其十六 纬","f":"五言律诗","c":["盈盈纬车妇，荆布事素朴。","丝丝理到头，的的出新濯。","心忙不遑食，腕倦何曾觉。","忽听归鸦啼，斜阳挂屋角。"]},{"t":"织图二十三首 其十七 织","f":"五言律诗","c":["一梭复一梭，频掷青灯侧。","艳艳机上花，朵朵手中织。","娇女眠齁齁，秋虫语唧唧。","檐头月渐高，纸窗明晓色。"]},{"t":"织图二十三首 其十八 络丝","f":"五言律诗","c":["女红亦颇劳，凄然当户叹。","灯昏络素丝，篗重困柔腕。","纤纤鬓影寒，沉沉夜气半。","妾心不敢忙，心忙丝绪乱。"]},{"t":"织图二十三首 其十九 经","f":"五言律诗","c":["昨为篗上丝，今作轴中轻。","均匀细分理，珍重相叮咛。","君看千万缕，始成丈尺绢。","城市纨绔儿，辛苦何尝见！"]},{"t":"织图二十三首 其二十 染色","f":"五言律诗","c":["深浅练縓纁，苍黄运巧智。","把丝晒柴荆，临风含绮思。","焕然五色纷，烂若云霞炽。","好语付机工，金梭织锦字。"]},{"t":"织图二十三首 其二十一 攀花","f":"五言律诗","c":["织绢当织长，挽花要挽双。","绪繁劳玉腕，梭冷烬银缸。","新样胜吴绫，斜文赛蜀锦。","成匹落谁家，讵忍栽衾枕！"]},{"t":"织图二十三首 其二十二 剪帛","f":"五言律诗","c":["千丝复万丝，成帛良非偶。","握尺重含情，欲剪频低首。","红分的的桃，青擘柔柔柳。","但免舅姑寒，妾单亦何丑。"]},{"t":"织图二十三首 其二十三 裁衣","f":"五言律诗","c":["九月届授衣，缝纫难容缓。","戋戋逐剪裁，楚楚称长短。","刀尺迎风寒，元黄委云满。","帝力并天时，农蚕慰饱暖。"]},{"t":"群仙册一十八首 其一 谭元","f":"五言律诗","c":["胜境邀仙侣，飞軿访上真。","瑶华拂星佩，沆瀣湿云巾。","饵玉颜含彩，怀丹气自春。","长生探秘诀，守寂炼形神。"]},{"t":"群仙册一十八首 其二 桃熟","f":"五言律诗","c":["移种瑶池畔，今看实压枝。","香含红熟透，露湿碧荣滋。","七颗盛盘日，千年乂摘期。","朝来谒金阙，甘美献天墀。"]},{"t":"群仙册一十八首 其三 赏荷","f":"五言律诗","c":["翠盖千重合，冰华万古清。","人寰夸玉井，仙露胜金茎。","质秀香尤异，波凉暑不生。","逍遥蓬岛内，未拟赴瑶京。"]},{"t":"群仙册一十八首 其四 鼓瑟","f":"五言律诗","c":["树树花如雪，层层玉作天。","芝栽成五色，鹤养已千年。","云帔来真侣，霞浆饮上仙。","和歌新制曲，宝瑟奏冰弦。"]},{"t":"群仙册一十八首 其五 鹿辇","f":"五言律诗","c":["白鹿充仙驭，青禽识羽童。","期朝太素帝，约会上清宫。","草拾瑶池畔，笙吹郁岛中。","更倾琼液酒，一醉寿春红。"]},{"t":"群仙册一十八首 其六 迎福","f":"五言律诗","c":["翠凝松万岁，香发桂双柎。","地接三清境，天开五福图。","童颜如冠玉，仙佩总垂珠。","行满虚皇召，骖鸾立可须。"]},{"t":"群仙册一十八首 其七 跨角兽","f":"五言律诗","c":["凌霄丹嶂迥，行处彩霞飞。","独角仙家骑，双童鸟羽衣。","遨游三岛遍，俯瞰九河微。","南极寻前约，云边启玉扉。"]},{"t":"群仙册一十八首 其八 戏狮","f":"五言律诗","c":["青猊原瑞物，长养属仙家。","迟日呼童子，春风试爪牙。","食惟衔露草，卧为护丹砂。","好献通明殿，天衢驭帝车。"]},{"t":"群仙册一十八首 其九 泛海","f":"五言律诗","c":["碧海长无浪，红云不作秋。","月槎飘一叶，莲瓣荡扁舟。","竞向银河渡，还从星渚留。","年年赓帝寿，元鹤记添筹。"]},{"t":"群仙册一十八首 其十 采苓","f":"五言律诗","c":["圣人长驭世，仙子启灵踪。","秘结千龄饵，香腴万载松。","雪霜凝珀质，龙虎护云封。","酿酒充尧斝，春光驻鹤容。"]},{"t":"群仙册一十八首 其十一 烧丹","f":"五言律诗","c":["铅砂和药物，松柏绕云坛。","炉运阴阳火，功兼内外丹。","光芒冲斗耀，灵异卫龙蟠。","自觉仙胎熟，天符降紫鸾。"]},{"t":"群仙册一十八首 其十二 巨桃","f":"五言律诗","c":["根盘红日近，枝耸碧云高。","阆苑邻青李，瑶池映翠涛。","偷须防曼倩，熟拟宴仙曹。","莫讶如瓜大，甘香胜玉膏。"]},{"t":"群仙册一十八首 其十三 步雪","f":"五言律诗","c":["绛雪呈奇瑞，琼枝花遍开。","昆仑银烂漫，碧落玉崔嵬。","粉蝶凌风舞，霜禽接翅来。","海天长不夜，真境识蓬莱。"]},{"t":"群仙册一十八首 其十四 桧下会真","f":"五言律诗","c":["太乙须眉古，虚皇冠佩尊。","元初参得一，天地论归根。","琼液卮卮满，琪花处处繁。","欣看前种桧，老干已龙鶱。"]},{"t":"群仙册一十八首 其十五 抚鹿","f":"五言律诗","c":["遥指蓬山麓，轩临弱水濆。","鹿驯眠细草，沙暖覆香云。","石亦含灵气，泉皆发异芬。","呦呦鸣未已，林外每呼群。"]},{"t":"群仙册一十八首 其十六 双鸾","f":"五言律诗","c":["一派箫璈涌，歌声云外飘。","青童擎羽盖，翠扇执垂髫。","晓籁鸣环玉，天风拂粉绡。","双鸾王母使，传简下层霄。"]},{"t":"群仙册一十八首 其十七 放鹤","f":"五言律诗","c":["白羽裁为氅，丹砂结作鬟。","九皋长啸后，华表复飞还。","岩洞烟霞侣，蓬瀛供奉班。","放教随意去，切莫恋尘寰。"]},{"t":"群仙册一十八首 其十八 授法","f":"五言律诗","c":["太上乘龙降，群真曳佩参。","灵科宣玉简，秘箓发金函。","传诀开丹鼎，焚香结紫岚。","侍仙通古篆，援笔录元谈。"]},{"t":"苫次述哀","f":"七言古诗","c":["慕思君父泪千行，四十余年顾复长。","高厚深恩悲罔极，瞻依情切托靡方。","天颜咫尺忽成隔，庭训趋承难再望。","提命谆谆犹在耳，樽彝肃肃总摧肠。","衔哀但觉苍旻远，举首惟悲白日凉。","展转心增风木恨，劬劳忍诵蓼莪章。","仙軿已返层霄上，夜梦仍亲御座傍。","海水可枯石可化，终天仰恋讵能忘！"]},{"t":"赐庄亲王","f":"五言律诗","c":["一本论瓜瓞，连枝喜最亲。","推恩先迩室，略分讲家人。","尽洗膏粱习，须教学业醇。","股肱兼耳目，属望更谆谆。"]},{"t":"赐裕亲王","f":"七言律诗","c":["朱邸连云翼紫宸，屏藩重望属亲臣。","银潢派接恩波近，玉叶枝分湛露新。","善体诒谋惟爱国，远承家法在勤民。","同心夹辅应无忝，常巩瑶图亿万春。"]},{"t":"赐怡亲王","f":"七言律诗","c":["天上根盘若木枝，朝阳辉映日纷披。","葵心北拱输丹禁，棣萼春荣护赤墀。","干济有才频入告，职司无缺亦书思。","忠勤佐就升平业，长保勋名奕世垂。"]},{"t":"赐果郡王","f":"七言律诗","c":["花萼连枝夹帝京，英才挺秀信维城。","冲和自保穰穰福，恭谨无劳赫赫名。","同气一堂亲燕笑，推恩千祀佐休明。","更期永矢忠勤节，长看盘根应候荣。"]},{"t":"赐大学士马齐","f":"七言律诗","c":["黄扉出入领朝簪，宿德耆英眷注深。","才是济川需作楫，功同望岁伫为霖。","常思国事如家事，益励臣心沃主心。","喜起明良传盛烈，薰风千载播瑶琴。"]},{"t":"赐大学士松祝","f":"五言律诗","c":["玉陛觇风度，金瓯卜姓名。","常时依紫极，何以福苍生。","化理资调燮，吁谟属老成。","公忠勤体国，力为赞升平。"]},{"t":"赐大学士白潢","f":"五言律诗","c":["密勿黄扉重，清时掌国均。","平成需弼亮，光辅贵经纶。","共勉三公职，无惭一个臣。","蓼萧多雨露，应及老成人。"]},{"t":"赐大学士徐元梦","f":"五言律诗","c":["位以中台峻，名因主眷高。","六卿推旧德，百职藉薰陶。","报国吁谟切，衔恩翊赞劳。","运筹称自昔，前席礼频叨。"]},{"t":"赐大学士张鹏翮","f":"五言律诗","c":["一德登黄阁，三台烛紫霄。","化功兼衮补，和气作羹调。","运轴推元老，持钧序庶僚。","赓歌应可嗣，赖尔协箫韶。"]},{"t":"赐大学士王顼龄","f":"七言律诗","c":["纶扉简命出宸衷，元老官仪自古隆。","帝德无私资赞化，臣心匪懈在抒忠。","勤宣天泽敷霖雨，善剂人情布巽风。","一德明良歌喜起，皋夔事业古今同。"]},{"t":"赐内大臣马武","f":"七言律诗","c":["禁御宣劳重近臣，貂蝉奕叶载恩纶。","入参帷幄抒丹悃，出典周庐翊紫宸。","镇静实堪心膂寄，老成尤见性情纯。","天家濊泽无私厚，勤恪应沾雨露频。"]},{"t":"赐尚书孙柱","f":"五言律诗","c":["卿月光华灿，朝廷任重臣。","分曹资辅国，列位济斯民。","正直先寮属，端严领缙绅。","所期宏伟略，报国不谋身。"]},{"t":"赐尚书朱轼","f":"五言律诗","c":["高岳生良佐，兴朝重老成。","南宫持藻鉴，北斗秉权衡。","忠岂惟供职，清能不近名。","眷言思共理，为国福苍生。"]},{"t":"赐尚书田从典","f":"七言律诗","c":["百工允敕重朝端，职典枢机未易殚。","出纳望同天北斗，清芬品拟省中兰。","分曹政洽调元气，补衮心悬效寸丹。","日昃共期劳庶绩，履声常听下金銮。"]},{"t":"赐尚书张廷玉","f":"五言律诗","c":["峻望三台近，崇班八座尊。","栋梁才不忝，葵藿志常存。","大政资经画，吁谟待讨论。","还期作霖雨，为国沛殊恩。"]},{"t":"赐尚书励廷仪","f":"五言律诗","c":["喉舌宣王命，纲维辖众僚。","星辰环紫极，剑履上青霄。","独坐心常凛，西曹法自昭。","昼思频献纳，退食肯逍遥？"]},{"t":"赐侍郎蒋廷锡","f":"五言律诗","c":["立政资良佐，宣猷重贰卿。","枢机同出纳，郎署仰澄清。","自合称华选，还期矢朴诚。","在公勤夙夜，懋绩有贤声。"]},{"t":"赐侍郎史贻直","f":"七言律诗","c":["率属分曹地望崇，位跻卿贰赖和衷。","彤墀迹蹑中台履，玉佩声含晓殿风。","勿惮贤劳亲吏职，好将兢业亮天工。","公忠不负衣冠选，槐棘均叨雨露同。"]},{"t":"癸卯十一月十三日恭遇圣祖仁皇帝忌辰缅怀顾复深恩瞻对无由不胜凄怆敬赋六韵以抒罔极之思","f":"七言古诗","c":["寝门不再省晨安，睽隔伤怀阅暑寒。","思慕情殷劳梦寐，几筵频展痛汍澜。","岁时每怆推迁易，恩德难忘覆载宽。","付托独深羞浅薄，命提莫望益悲酸。","天心此日犹能复，圣范无时更奉欢。","瞻对御容风木惨，何禁哀涕欲摧肝。"]},{"t":"耕耤","f":"五言律诗","c":["农事惟邦本，先民履亩东。","翠华临广陌，彩轭驾春风。","礼备明神格，年期率土丰。","劝耕时廑虑，敢为惜劳躬？"]},{"t":"诣太学","f":"七言律诗","c":["礼乐牖民资大化，国家造士在斯文。","临雍观礼崇儒切，视学论经养俊殷。","济济桥门龙旆绕，雍雍璧水凤毛纷。","千宫咸庆文明盛，还伫同风率土欣。"]},{"t":"三月三日得雨","f":"七言律诗","c":["三春淑气动萌荄，膏雨知时四野皆。","东作共看沾溉足，西成咸庆岁时谐。","柔桑陌上青含秀，稚麦田间绿正佳。","伫览霏霏飘洒意，眷予兆庶少抒怀。"]},{"t":"赐大学士张鹏翮暂假葬亲","f":"七言律诗","c":["孝思忠悃本相成，蜀道迢迢去帝京。","自是白云增恋慕，非关绿野乐幽清。","松楸得展酬亲志，魏阙长悬报国情。","好待泷冈封马鬣，速还黄阁赞升平。"]},{"t":"母后周年述哀一首","f":"古风","c":["慈恩重，难禁涕泪悬。","尊荣心莫罄，恍惚岁云迁。","物候常如此，音容独渺焉。","寝门空在望，一望一凄然！"]},{"t":"述杯","f":"五言古诗","c":["眇躬临亿兆，兢业凛渊深。","先哲羹墙见，前徽手泽寻。","弛张遵祖训，赏罚顺天心。","庶绩勤宵旰，微几慎影衾。","卫诗防湎酒，夏训戒从禽。","每喜亲耕稼，长怀劝织纴。","菽葵村落圃，桑柘水边林。","民乃邦之本，诚为帝所歆。","三冬盈瑞雪，九有遍甘霖。","岁稔田家乐，河清渔父吟。","群英襄治理，列士献规箴。","勉咏南薰曲，多惭继舜琴。"]},{"t":"冬至斋宫二首 其一","f":"七言律诗","c":["晨曦炯炯洁斋宫，一缕炉烟散绮栊。","暖气潜回葭琯律，早梅先绽玉阶风。","中孚默契天人理，来复明彰造化功。","漫道书云成故事，精禋惟藉寸心通。"]},{"t":"冬至斋宫二首 其二","f":"七言律诗","c":["凌寒松柏耐严冬，带月含霜度禁钟。","午夜无眠思戒凛，诘朝崇祀务斋恭。","初阳鼓动开三殿，万象昭回映九重。","嘉节届临生意始，虔祈上帝惠吾农。"]},{"t":"甲辰十一月十三日恭值皇考二周忌辰感时永慕哀痛填膺洒泪述哀敬成一律","f":"七言律诗","c":["霜露重惊岁月侵，抚时莫解感伤心。","慕思实切终身永，恩德难酬罔极深。","那得寝门重问膳，每怀圣训更沾襟。","朝来回忆前年事，痛抱终天自古今。"]},{"t":"是日瞻拜御容追忆慈颜不胜悲怆再成一律","f":"七言律诗","c":["屈指违颜岁再周，飞光逝水两难留。","圣仪秋肃钦渊默，天语春温想喔咻。","荐食哀生松殿里，捧觞泪洒玉阶头。","兢兢继述何堪道，服训常怀负荷忧。"]},{"t":"耕耤诗","f":"五言律诗","c":["苍驭千官引，乘时事耤田。","从来重稼穑，何敢惜劳先？","履亩迎膏发，群公继耦联。","所祈同亿兆，岁岁介丰年！"]},{"t":"雍正三年乙巳二月十有二日皇考服制告除违情从礼溯时增怆敬述纪哀","f":"七言律诗","c":["告袷今朝怆益滋，服除从吉礼从宜。","频看冉冉流光转，每虑悠悠报德亏。","承大业惟循夙训，念诒谋祗奉成规。","无如瞻恋终难及，莫罄缠绵结永思。"]},{"t":"初夏偶闲","f":"七言律诗","c":["清闲偶得万几余，水殿蓬壶九夏初。","夜听甘霖浇沃野，晓看佳气绕宸居。","绿荷池畔吟新句，翠竹林中披异书。","时领薰风知解愠，松涛缓送度窗虚。"]},{"t":"母后二周讳辰","f":"五言律诗","c":["自隔慈颜杳，重临此日悲。","音徽徒有慕，尊养已无时。","恩念劬劳重，心惊岁月驰。","朝来益为怆，抚序泪空垂。"]},{"t":"赐庄亲王","f":"七言律诗","c":["金章玉佩冠通侯，班列彤阶最上头。","仪表宗潢高乐善，屏藩王室重宣猷。","桐圭分锡开朱邸，棣萼联辉映凤楼。","捧日丹忱勤翼赞，天家恩泽自长流。"]},{"t":"赐果郡王","f":"五言律诗","c":["天潢崇锡爵，宗子重维城。","共荷屏藩寄，知敦翼赞情。","好书传沛献，乐善纪东平。","望古几前哲，相期保令名。"]},{"t":"乙巳仲冬追亿皇考升遐倏周三载孺慕之忱与时俱积恭诣景陵拜谒以伸哀痛","f":"七言律诗","c":["恭陈服御俨凭依，拜奠菁茅凛不违。","四十年余恩浃髓，一千日里涕沾衣。","寝园翠绕熊罴护，陵树霜寒鸟雀稀。","翘首五云犹在望，忍乘清跸告言归。"]},{"t":"暮春野望","f":"七言律诗","c":["户牖凌虚百尺楼，川原霁色坐中收。","绿萝灌水园蔬茂，碧浪翻风垄麦稠。","杨柳坡边眠牧竖，杏花树畔泊渔舟。","升平睹此丰年景，更亿英贤济远猷。"]},{"t":"闲咏","f":"七言律诗","c":["苑柳千条拂地垂，红尘飞不到轩墀。","炷余古鼎睛烟袅，题罢长笺昼漏移。","松影参差摩诘画，禽声上下浩然诗。","遥空喜见浓云合，恰是吾民望雨时。"]},{"t":"母后三周讳辰","f":"五言律诗","c":["鞠我恩深重，违颜梦渺茫。","三年成逝水，百感对流光。","黯黯慈云在，迢迢仙路长。","朝来又临讳，含怆仰空苍。"]},{"t":"偶题","f":"七言律诗","c":["舜禹传心十六字，执中一语贯精微。","漫从体用观真妄，不向筌蹄觅是非。","大地春风扬道妙，碧天秋月露清机。","个中密谛何人会，鱼自深潜鸟自飞。"]},{"t":"月夜听泉声得句","f":"七言律诗","c":["逶迤洲渚薜萝幽，苑静偏宜秉独游。","万树林梢看月上，三峰岩畔听泉流。","溅衣珠洒晴疑雨，戛玉湍鸣夏似秋。","风激潺湲声不断，夜深恋赏未回舟。"]},{"t":"知鱼亭待月","f":"七言律诗","c":["传呼不用上林丞，傍水登临远郁蒸。","解渴漫调金掌露，清心胜饮玉壶冰。","知鱼亭畔观鱼跃，得月台前望月升。","烟敛碧池星汉皎，玉栏高处尽堪凭。"]},{"t":"赐怡亲王","f":"七言律诗","c":["勤政楼头花萼芳，亲贤心膂藉匡襄。","忠诚谨慎谟猷著，公正廉明誉望彰。","经理度支需赞画，畴咨水土奏丰穰。","年年景福由天赐，长秉丹衷达九阊。"]},{"t":"赐侍郎沈近思","f":"五言律诗","c":["冢宰官资贵，寅恭属亚卿。","俱邀三命重，并列六曹荣。","操比寒潭洁，心同秋月明。","所期庶政理，海宇日澄清。"]},{"t":"赐总督查弼纳","f":"七言律诗","c":["时雍佳气浃寰瀛，绣戟牙幢制阃荣。","两省风霜澄吏治，三春雨露洽舆情。","位高定效公忠实，职钜非循廉谨名。","文武兼资才自裕，伫期嘉绩佐升平。"]},{"t":"赐总督杨宗仁","f":"七言律诗","c":["绛节金章制上游，雄藩兼控主恩优。","分疆名帅归钤辖，绣错方州待运筹。","文武和衷群吏宪，军民一体大臣猷。","殷勤早夜遵天语，会见酬庸第一流。"]},{"t":"赐总漕张大有","f":"五言律诗","c":["天储关国计，输挽最艰辛。","舰轴来千里，膏脂念万民。","无忧任土贡，已得济川人。","岂靳功高赏，恩光宠锡频。"]},{"t":"步月至泉畔试茶","f":"七言律诗","c":["飞阁流云护碧纱，曲栏掩映竹阴斜。","巡檐步月敲奇句，坐石烹泉品贡茶。","乳液清逾花上露，春旗嫩展雨前芽。","水天一色明如昼，照见溪鱼戏浅沙。"]},{"t":"闻雁","f":"七言绝句","c":["万机听览省行游，镜里韶华逐水流。","木叶荣枯纪岁月，雁声南北报春秋。"]},{"t":"观瀑布","f":"七言律诗","c":["风过林静片云还，物外逍遥意趣闲。","鴷鸟扣关声剥啄，涧流喷雪响潺湲。","光寒古鉴飞霜练，翠滴晴岚涤雾鬟。","岂必蓬瀛夸胜迹，翛然清境在人间。"]},{"t":"湖际闻野寺钟声","f":"七言律诗","c":["长伴予游鹤与松，何烦扈跸得从容。","湖烟淡罨迎人月，山寺遥传定夜钟。","不问清修谈内典，懒将密意叩南宗。","悠然梵响因风送，暗数云林第几峰。"]},{"t":"月","f":"七言律诗","c":["宝镜奁开升自东，星疏云净正秋中。","从看圆洁今宵满，即此晶辉万古同。","奕奕荣光蟾吐彩，溶溶澄景水明空。","当筵坐爱团圞好，时得香飘桂子风。"]},{"t":"仲丁祭文庙","f":"七言律诗","c":["扶植纲常百代陈，天将夫子觉斯民。","帝王师法成隆治，兆庶遵由臻至淳。","道统常垂今与古，文明共仰圣而神。","功能溯自生民后，地辟天开第一人。"]},{"t":"耕耤","f":"五言律诗","c":["无逸农功重，豳风穑事先。","方春勤夙驾，乘令为亲田。","夹陇千官肃，扶犁百辟联。","礼成终亩后，父老庆丰年。"]},{"t":"夏夜不成寐","f":"七言律诗","c":["疏帘香散御炉烟，万井沉沉翠幔悬。","夜静梵音来水面，月明渔唱到窗边。","虚堂虑息难成寐，冰簟心清即入禅。","惟有团团荷上露，晶莹可拟意珠圆。"]},{"t":"雨后湖亭看月","f":"七言律诗","c":["鄙听秦声却楚优，每于山水暂淹留。","翠含宿雨千竿竹，高出层云百尺楼。","湖影远浮随棹月，柳塘斜系钓鱼舟。","坐深暑退凡情爽，一片清光入镜流。"]},{"t":"宫中偶成","f":"七言绝句","c":["紫禁遥闻玉漏迟，露华滴遍万年枝。","风帘不动尘喧隔，月满瑶阶意孰知。"]},{"t":"赐淳亲王","f":"七言律诗","c":["满树繁花应候荣，蟠根奕叶托瑶京。","试看花萼相承意，更听埙篪迭和声。","带砺永存苗裔业，豆笾有践弟昆情。","天朝屏翰家庭事，莫负皇心眷顾诚。"]},{"t":"赐都统拉锡","f":"七言律诗","c":["羽林十二应星文，直宿周庐向夜分。","阵识风云才自裕，身依日月志弥勤。","鹰扬早领熊罴士，虎拜常参鹓鹭群。","办得丹心捧宸极，时清莫漫羡奇勋。"]},{"t":"赐提督郝玉麟","f":"七言律诗","c":["元戎拥节镇岩疆，特简殊荣姓氏香。","阃外长城资一面，胸藏武库靖多方。","旌旗整暇军容肃，纪律严明士气扬。","盛世筹边重颇牧，枫宸应为锡龙光。"]},{"t":"赐提督高其位","f":"七言律诗","c":["太和累洽庆櫜弓，专阃还推赫濯功。","裨益军民资伟略，剂调文武在和衷。","拊循正及从容日，谋勇皆由训练中。","元老旗常书茂绩，雅歌应有穆如风。"]},{"t":"桃花坞即景","f":"七言律诗","c":["禁园宜雨复宜晴，别馆春深枕簟清。","数片落花惊午梦，一声渔唱惹闲情。","暂移榻向松间坐，恰听禽来竹里鸣。","惟有东风知我意，满池新绿浪纹生。"]},{"t":"诣太学 其一","f":"五言律诗","c":["辟雍亲莅止，典礼重参稽。","管龠仍鱼雅，威仪自整齐。","礼门资至化，义路牖群黎。","永翊文明治，休征共受禔。"]},{"t":"诣太学 其二","f":"五言律诗","c":["善俗礼为本，仁民域可跻。","崇儒申术教，造士列东西。","共式习如性，咸成璋与圭。","兴贤勤寤寐，振德日提撕。"]},{"t":"春夜钓鱼矶闻笛","f":"古风","c":["暮雨一帘初卷，东风万卉齐芳。","隔林渔火明灭，沿溪笛韵悠扬。"]},{"t":"会心处试笔","f":"古风","c":["秋霁瑶台晚眺，夜深便殿宵衣。","神会园林妙趣，心勤一日万机。"]},{"t":"桃源深处","f":"古风","c":["溪外每闻犬吠，林间日听莺声。","漫问武陵何处，且来此地移情。"]},{"t":"响泉山房赏月","f":"五言古诗","c":["薄暮鸣蝉歇，松涛响曲廊。","清阴生殿阁，霁色映林塘。","皎洁银河近，迢遥玉漏长。","波飘菰米滑，风动藕花香。","坐石吟新月，临流纳晚凉。","一钩才吐艳，灿烂隐萤光。"]},{"t":"仁明斋咏怀","f":"七言律诗","c":["忆昔园林趋觐回，朱门静掩不轻开。","怡情看竹邀僧话，余事移松傍水栽。","勤政原因涵养到，任劳却自静功来。","万机日日如丝绪，勉竭心思手自裁。"]},{"t":"沿湖游览至菜圃作","f":"七言律诗","c":["一行白鹭引舟行，十亩红渠解笑迎。","叠涧湍流清俗念，平湖烟景动闲情。","竹藏茅舍疏篱绕，蝶聚瓜畦晚照明。","最是小园饶野致，菜花香里辘轳声。"]},{"t":"帝京篇","f":"五言古诗","c":["磐石占幽蓟，金汤固帝京。","幅员宁有外，带砺自堪盟。","形势河山拱，星文气象清。","休征荷地力，瑞应感天成。","济济匡时器，熙熙击壤情。","溪流穿禁籞，霞彩映重城。","日照朱甍丽，尘飞紫陌轻。","烟花织锦绣，莺燕唱升平。","池暖鱼吹絮，兰熏蝶抱英。","新荷初浥露，宿麦晚蒸晴。","极浦渔舟杳，斜阳牧笛横。","所希均雨泽，南亩问春耕。"]},{"t":"舟中纳凉","f":"七言律诗","c":["开遍芙渠水为香，疏槐鸦影乱昏黄。","停舟待月寻佳句，卷幔吟风纳晚凉。","渔笛数声飘远岸，茶烟一缕扬修篁。","畅舒心志逢清夏，寂寂花阴漏正长。"]},{"t":"赐怡亲王二首 其一","f":"古风","c":["皇皇藩服，惟德是荣。","眷言贤王，谟猷光明。","夙夜小心，以忠以诚。","弼予一人，庶绩用成。","嘉兹翊赞，朱邸斯营。","上栋下宇，永安且宁。","有策其基，有壮其楹。","奕世承之，长卫帝京。","庆既令居，式昭颂声。"]},{"t":"赐怡亲王二首 其二","f":"七言律诗","c":["惇族由来重本支，贤声况复叶埙篪。","心悬北阙知忠悃，第赐东华表令仪。","禁院联辉双蒂树，上林移植万年枝。","永惟堂构资寅亮，载咏南山福禄宜。"]},{"t":"暮春杂咏 其一","f":"七言律诗","c":["春云澹荡满平湖，渺渺烟波接绿芜。","芳甸雨过花竞笑，画桥风起柳相扶。","莺歌鸟语天然曲，水秀山清自在图。","胜景已超尘世界，何须驾海访蓬壶。"]},{"t":"暮春杂咏 其二","f":"七言律诗","c":["炉烟袅袅拂帘栊，太液波澄晓镜融。","卜岁喜看三月雨，惜春深坐百花风。","红尘不到黄金阙，香雾时遮碧玉宫。","对此上林光景好，清平愿与万方同。"]},{"t":"夏日勤政殿观新月作","f":"七言律诗","c":["勉思解愠鼓虞琴，殿壁书悬大宝箴。","独揽万机凭溽暑，难抛一寸是光阴。","丝纶日注临轩语，禾黍常期击壤吟。","恰好碧天新吐月，半轮为启戒盈心。"]},{"t":"雨后九洲清宴望西山","f":"七言律诗","c":["蒹葭叶上雨声过，乍觉新凉飒飒多。","山色崔嵬千叠翠，湖光潋滟万重波。","游鱼避钓依寒藻，翔鸟惊弦就碧萝。","莫讶金风催改序，秋晖偏好快晴和。"]},{"t":"仲秋月夜题于清会亭","f":"七言律诗","c":["深沉院宇桂香浮，寂寂溪园色相幽。","静向庭中持佛偈，闲来月下泛扁舟。","云迷入梦林间鹤，浪逐忘机水面鸥。","对此清光神会处，岸芦汀蓼一天秋。"]},{"t":"新霁苑中秋色颇佳临流玩赏率成一律","f":"七言律诗","c":["步辇从容雨后临，湖亭景物可追寻。","幽花戏蝶红芳晚，密藻潜鳞碧涨深。","寥泬天光增远趣，潺湲涧水静尘心。","闲游不用调丝管，自有松篁奏好音。"]},{"t":"喜雪","f":"五言律诗","c":["夙夜期琼屑，三冬日见晴。","省修求直谏，祈祷秉精诚。","瑞雪春时降，彤庭喜气盈。","苍旻仁爱普，亿兆荷生成。"]},{"t":"戊申除夕守岁","f":"五言律诗","c":["送腊迎新节，年过半百初。","道心随日进，佳兴逐时舒。","宝鼎宫香蔼，瑶阶瑞雪余。","载欣丰裕兆，大有望频书。"]},{"t":"春夜永春亭作","f":"七言律诗","c":["霏微池馆罨春烟，银汉迢迢淑景妍。","鱼跃清波惊犬吠，月穿绿柳觉莺眠。","折蕉戏写题花句，接竹斜通傍槛泉。","良夜寸阴应共惜，岂容虚度艳阳天。"]},{"t":"百花亭春咏","f":"七言绝句","c":["涟漪碧水浸苔痕，垂柳丝丝静掩门。","月上海棠惊鸟梦，雨来庭院浴花魂。"]},{"t":"几暇偶题","f":"五言绝句","c":["识得几暇趣，丝纶不假言。","孰知宵旰里，却是绝尘喧。"]},{"t":"暮春有感","f":"七言律诗","c":["虚窗帘卷曙光新，柳絮榆钱又暮春。","听政每忘花月好，对时惟望雨旸匀。","宵衣旰食非干誉，夕惕朝乾自体仁。","凤纪分颁虽七度，民风深愧未能淳。"]},{"t":"如意歌赐怡亲王","f":"七言古诗","c":["彩云冉冉鸾鹤翩，鸾鹤背驭双神仙。","南极西池环佩联，双双同庆帝胄贤。","手执如意来当前，篆刻蝌蚪黄金填。","晶荧上下星文缠，瑶台此日喜气偏。","琅琅更听仙语传，唱随偕老如和弦。","既指山海为岁年，复言日月同团圆。","煌煌带砺眷便便，子孙永保福且绵。","予因仙语嘉喜骈，为尔歌双如意篇。"]},{"t":"朕御极七载宵旰万几未遑他出己酉夏因命将远讨誓师于南海子缅怀曩日侍奉皇考巡幸此地色笑俨在目前而龙驭杳然邈不可攀俯仰徘徊曷胜今昔之感爰成一律以述追思","f":"七言律诗","c":["花开野甸不知名，接辔依然辇路平。","细草当时随驻跸，垂杨此日绕行营。","河山满目音容邈，风景关心岁月更。","禁旅多年蒙教养，畀予戡定作干城。"]},{"t":"己酉夏南甸大阅 其一","f":"七言律诗","c":["陈师鞠旅卜良朝，万里糇粮备已饶。","习战自能闲纪律，临戎惟在戒矜骄。","剑莹鸊鹈清光闪，旗绕龙蛇赤羽飘。","听彻前锋歌六月，云台合待姓名标。"]},{"t":"己酉夏南甸大阅 其二","f":"七言律诗","c":["风拂榆槐晓角鸣，筑坛选将命专征。","飕飕羽箭穿杨巧，猎猎云旓耀日明。","万里玉关平虏穴，三秋瀚海渡天兵。","裹粮带甲须珍重，扫荡尘氛远塞清。"]},{"t":"秋日登四佳楼晚眺","f":"七言律诗","c":["庶务纷纭综理暇，偶将幽兴寄泉林。","楼台况复秋光洁，花木偏宜霁景临。","西岭层峦千叠翠，东湖细浪万重金。","澹烟轻霭疏槐杪，接阵鸿归夕照沉。"]},{"t":"月夜平湖放舟","f":"七言律诗","c":["风卷平湖玉簟纹，沙汀落叶正纷纭。","微微隔岸萤光隐，历历横空雁字分。","碧浪载舟舟破浪，白云笼月月穿云。","渺然秋爽超凡界，欲问西山鸾鹤群。"]},{"t":"偶占","f":"七言绝句","c":["碧桃吐艳莺初啭，丹桂含芳燕又归。","日往月来传大道，花香鸟语泄真机。"]},{"t":"仲秋月夜感怀","f":"七言律诗","c":["碧天皓魄印长空，嘹呖初闻度塞鸿。","榴子结成崖石畔，桂香飘入渚烟中。","溪环松老重添翠，岩映枫疏半缀红。","追忆昔年秋夜宴，不禁此际感西风。"]},{"t":"追忆旧景有感","f":"七言古诗","c":["时名向鄙倩人推，洗竹浇花坐钓台。","画舫新晴看月上，平桥细雨送春回。","行无干誉心恒逸，境不移情量自恢。","萧散当年吟独乐，忧勤今日觅群材。","民风浇薄须陶化，世态参差待品裁。","览疏宵忘泉石美，临朝晓听鼓钟催。","纤毫坐悉千官奏，方寸频劳庶务来。","追忆安闲成梦幻，双眉锁处阿谁开？"]},{"t":"偶成","f":"七言绝句","c":["晴空瞬息片云生，风卷千堆雪浪惊。","石虎泥龙争斗罢，澄潭涌出月轮明。"]},{"t":"又","f":"七言绝句","c":["长空万里碧天秋，绝点纯清亦不收。","识得如如妙中妙，尘尘刹刹任悠悠。"]},{"t":"赐总督高其倬","f":"七言律诗","c":["崇牙高建秉洪钧，远控岩疆轶等伦。","两省山河司管钥，万民肥瘠视经纶。","还持绛纛开军垒，永矢丹忠答禁宸。","操凛冰霜功带砺，匡时重镇眷良臣。"]},{"t":"赐总督李卫","f":"七言律诗","c":["保障鸿才奏绩新，每将重寄委贤臣。","须知令器承殊眷，贵有丹忱答紫宸。","训练多方资辑旅，抚绥无怠在諴民。","龙章用锡昭旌劝，益勖嘉猷辅一人。"]},{"t":"平湖秋月","f":"五言律诗","c":["树杪暮烟收，晴光逐水流。","浅沙闲立鹭，轻浪稳眠鸥。","心月双圆镜，湖天一色秋。","恍疑星汉里，缥渺玉京游。"]},{"t":"长至日题于至诚不息轩","f":"七言律诗","c":["殿角星疏报曙钟，乾乾无逸每忧农。","葭灰协律云占岁，粉絮翻阶雪应冬。","时对神明持敬念，日临兆庶用中庸。","愿言四海升平共，莫道尊安属九重。"]},{"t":"朕因去冬未雪忧怀莫释夙夜竭诚祈祷于惊蛰后二日荷蒙上天鉴佑春雪下降朝野同欢因成一律用志欣庆","f":"七言律诗","c":["霢霂愆期忧岁俭，临轩愁咏悯农歌。","三冬望雪心如渴，此日飞英气始和。","苍昊垂慈施恺泽，黔黎有幸沐恩波。","遥思九土应同庆，积素凝华知几多？"]},{"t":"圆明园道中寓日","f":"五言律诗","c":["御园西郭外，初夏景堪娱。","金线遮桥柳，浓阴夹道榆。","麦翻千顷浪，鱼跃半池珠。","雨后平芜绿，尘清辇路濡。"]},{"t":"多稼轩劝农诗","f":"五言律诗","c":["夜来新雨过，畿甸绿平铺。","克尽农桑力，方无饥冻虞。","蚕筐携织妇，麦饭饱田夫。","坐对春光晚，催耕听鸟呼。"]},{"t":"哭怡贤亲王二首 其一","f":"五言律诗","c":["宗室屏藩重，朝端柱石崇。","持身惟正直，应物本虚公。","青史经天略，丹心贯日忠。","衔哀为作诔，难与述丰功。"]},{"t":"哭怡贤亲王二首 其二","f":"五言律诗","c":["穗帐陈筵日，云軿载道时。","悲深万民泪，痛失百寮师。","献替犹如昨，仪容俨在斯。","可怜风雨急，花萼损连枝。"]},{"t":"怡贤亲王挽诗三十韵","f":"七言古诗","c":["天锡亲贤笃本支，惟王德业赞纯熙。","功存廊庙寰区仰，道冠宗藩百辟仪。","少日温恭承帝眷，髫龄孝谨荷恩慈。","问安每候龙楼启，扈跸常随豹尾驰。","圭璧精神昭粹质，风麟苞彩擅英姿。","自然才艺该文武，卓尔端凝绝党私。","三纪无惭臣子道，八年攸赖股肱资。","溯从大统祗承日，历想嘉猷翊辅时。","佐理万几安亿兆，综厘庶政挈纲维。","度支式定邦财裕，水利功兴浩泽施。","减赋蠲逋勤布算，栉风沐雨劝镃基。","淤流通外成膏壤，田垄开时养稻粢。","九品抡才分玉石，六韬训士总熊罴。","霜威秋肃明条教，恺泽春温善抚绥。","万里边防襄庙算，两军输挽佐畴咨。","任兼宫府仔艰钜，理析豪厘辨等差。","伟绩固难更仆数，清标更系久长思。","撝谦不恃金枝贵，精白匪求黼座知。","乐善荐贤时亹亹，奉公体国日孜孜。","宽仁恤下孚群望，廉洁居心凛自持。","八字褒崇皆实行，四时赐赉必晴曦。","庆流正喜天人合，善积还期福禄宜。","岂意赓扬方际盛，忽惊寝疾永睽离。","鞠躬遑恤身前汁，矢志空余没后悲。","犹忆恳情辞吉地，竟循薄葬守遗规。","公卿徒步随旌仗，老稚扶观泣路歧。","赠谥载光崇德典，加坛还树册勋碑。","明祀配享千秋重，素服衔哀浃月期。","纵极宠荣颁礼数，难酬懿美罄言词。","应知灵爽归仙籍，留得鸿名万古垂。"]},{"t":"夜静","f":"七言律诗","c":["星汉斜临避暑宫，石栏干曲绿阴笼。","风回岩畔泉声咽，夜静人闲月镜空。","绕砌兰薰香馥郁，满壶冰洁玉玲珑。","隔帘漏断天如洗，新句吟成一枕中。"]},{"t":"松月吟","f":"七言绝句","c":["香飘桂子月初盈，凉泛松涛溪共鸣。","丛桂影中和月影，万松声里听溪声。"]},{"t":"谒西山大觉寺","f":"七言律诗","c":["重开香积奉金仙，松径纡回警跸传。","野鸟静吟僧院竹，梵钟遥度御炉烟。","清幽水树红尘外，寂历云山太古前。","自有庄严超色相，何须慧远论真禅。"]},{"t":"秋分前二日月下作","f":"七言律诗","c":["露湿天阶夜景赊，湘帘高卷树栖鸦。","寒蛩唧唧吟深砌，曲沼盈盈涨浅沙。","风度桂丛香馥郁，月穿竹篽影横斜。","襟怀凄爽秋将半，落叶萧萧菊欲华。"]},{"t":"暮秋","f":"五言律诗","c":["散步御园东，清溪跨玉虹。","一亭风冷淡，叠砌石玲珑。","秋老松含翠，霜浓柿缀红。","萧然天气肃，云外度征鸿。"]},{"t":"花下偶成","f":"七言绝句","c":["对酒吟诗花劝饮，花前得句自推敲。","九重三殿谁为友，皓月清风作契交。"]},{"t":"清闲","f":"七言绝句","c":["世间何处觅清闲，只在朝堂城市间。","即此是非名利客，何殊野衲闭禅关。"]},{"t":"口占","f":"古风","c":["花谢花开寒暑，雁来雁往春秋。","惟有壶中日月，无今无古无休。"]},{"t":"仰瞻星垣","f":"七言律诗","c":["桂香芬馥夜凉生，露咽吟蛩万籁清。","碧汉接楼森斗宿，银河映沼转玑衡。","云开八表情无极，鹤杳三峰梦不成。","此际寸心同朗月，微垣历历湛虚明。"]},{"t":"永春亭留春","f":"五言律诗","c":["小池风力软，槛外柳阴交。","花点游鱼藻，泥香乳燕巢。","淡烟浮水面，纤月挂松梢。","恋咏留春句，题笺未忍抛。"]},{"t":"年华迅速倏值端阳箱贡冰纨案陈角黍于颁赐诸王大臣之际念及吾弟怡贤亲王仙游已周一载不禁凄然涕下援笔赋此","f":"七言律诗","c":["韶光荏苒暗中迁，开到榴花又一年。","节届香蒲陈似旧，贡来细葛赐谁先？","检文悲览贤臣颂，搦管慵裁棣萼篇。","伟绩殊勋无可答，为营佳兆表新阡。"]},{"t":"国家为准噶尔跳梁不得已有用兵之举自己酉以来将帅士伍枕戈负盾野宿风餐三载于兹矣朕每一廑念食不甘味寝不安席因避居便殿停御宴会日与廷臣筹计军需惟冀上苍默佑师旅早旋论功颁赏朕怀始释爰作截句四首以见意 其一","f":"七言绝句","c":["天禄崇儒方偃武，长杨罢猎岂佳兵。","无端戍火明西塞，劳我星旗向远征。"]},{"t":"国家为准噶尔跳梁不得已有用兵之举自己酉以来将帅士伍枕戈负盾野宿风餐三载于兹矣朕每一廑念食不甘味寝不安席因避居便殿停御宴会日与廷臣筹计军需惟冀上苍默佑师旅早旋论功颁赏朕怀始释爰作截句四首以见意 其二","f":"七言绝句","c":["月照天山玉帐高，风吹霜气透征袍。","年来倦听喜禾颂，一饭宁忘汗马劳。"]},{"t":"国家为准噶尔跳梁不得已有用兵之举自己酉以来将帅士伍枕戈负盾野宿风餐三载于兹矣朕每一廑念食不甘味寝不安席因避居便殿停御宴会日与廷臣筹计军需惟冀上苍默佑师旅早旋论功颁赏朕怀始释爰作截句四首以见意 其三","f":"七言绝句","c":["玉门关外草连天，一骑飞驰到日边。","报道单于甘就抚，羽林齐唱凯歌旋。"]},{"t":"国家为准噶尔跳梁不得已有用兵之举自己酉以来将帅士伍枕戈负盾野宿风餐三载于兹矣朕每一廑念食不甘味寝不安席因避居便殿停御宴会日与廷臣筹计军需惟冀上苍默佑师旅早旋论功颁赏朕怀始释爰作截句四首以见意 其四","f":"七言绝句","c":["将军跨马拥戈矛，壮士驱车久未休。","一纸捷书期早至，黄金铸印待封侯。"]},{"t":"环秀山房对月","f":"五言律诗","c":["暑退林泉爽，新秋景物佳。","蛩吟依藓砌，鹤迹印溪沙。","搁笔评山色，擎怀对月华。","坐深群籁寂，竹树影横斜。"]},{"t":"观释典偶题","f":"七言绝句","c":["浑忘云驶月轮迟，不悟舟行觉岸移。","世界三千皆有量，慧珠一颗净无涯。"]},{"t":"秋日登楼有感","f":"七言律诗","c":["尺璧谁言抵寸阴，旷然怀抱豁登临。","放情缅邈云峰古，极目苍茫烟水深。","犹忆童年花下戏，倏经鹤发鬓边侵。","眼前秋色当堪赏，况复新晴月满襟。"]},{"t":"除夕","f":"五言绝句","c":["今年今夕送，明岁明晨迎。","只此忧勤念，乾乾无灭生。"]},{"t":"晚晴远眺","f":"古风","c":["垂柳阴阴亭榭，落花点点池塘。","情怡平林暮霭，目极芳草斜阳。","水硙溪边自转，鱼罾篱外谁张？","万里清光皎洁，数声笛韵悠扬。"]},{"t":"端阳前一日为吾弟怡贤亲王二周之辰每一回思辄伤怀抱作五言律志感","f":"五言律诗","c":["诘朝端午节，再命罢称觞。","岁月如流迈，容仪何日忘。","安邦思柱石，觅句梦池塘。","物候频增感，情随彩缕长。"]},{"t":"去冬无雪今春雨未沾足朕心忧畏莫可言喻幸于前五月十八日甘霖倾注枯焦顿解不觉喜而成咏","f":"五言律诗","c":["节过五月半，膏雨尚愆期。","昼夜忧农事，精虔吁帝慈。","风回云气合，泽沛野苗滋。","田畯须勤课，耘耔正及时。"]},{"t":"深柳读书堂消夏","f":"七言律诗","c":["麴尘绿染万条丝，窣地浓阴暑暗移。","旋渍霜毫铺玉版，细研荷露写新诗。","一天月色画图古，两部蛙声鼓吹奇。","潇洒楼台临碧水，夜深倒影静垂垂。"]},{"t":"秋日寓目成咏","f":"七言律诗","c":["玉露金飙肃昊穹，澄泓秋水映帘栊。","群峰黛染呈寒碧，远浦霞明荡晚红。","风度桂林香满院，月穿雁字影书空。","予怀喜慰西成候，多稼如云处处同。"]},{"t":"秋夜印月池作","f":"五言律诗","c":["雨后添新涨，盈盈碧沼深。","临流洗俗耳，对月静尘心。","松引仙禽舞，萍摇锦鲤沉。","飒然风拂面，翠竹助清吟。"]},{"t":"壬子岁九月七日吾弟怡贤亲王定窆于水东村朕念手足至谊兼以辅弼功勤献替忠款抚今忆昔情不能已因亲临奠送稍伸积痛夫神游于天魄藏于地亘古迄今理之常也但以吾弟之亲贤为国家柱石幽明异路于兹永别当深秋草木黄落之际朕心曷胜凄怆爰赋此诗以写怀","f":"七言律诗","c":["西风瑟瑟草离离，惨对灵筵奠酒卮。","荆树凋残惊日晚，雁群零落入云悲。","邈焉不返游仙梦，行矣休歌薤露词。","此际亲临无限痛，九泉英爽料应知！"]},{"t":"暮春四宜堂咏怀","f":"七言律诗","c":["花繁如锦草如茵，雨细风轻物候新。","朱邸舞筵成往事，斑衣戏彩久凝尘。","万几宵旰忙中趣，百岁光阴梦里真。","不问春归何处去，惟听燕语报芳辰。"]},{"t":"荷池玩月","f":"七言律诗","c":["闲行傍水觉清凉，半刻徘徊百虑忘。","月上园林添秀色，风来池沼送幽香。","红衣露坠莲房粉，素练光凝镜面霜。","夜静暑消多野趣，悠然自得咏沧浪。"]},{"t":"立秋前二日游湖亭","f":"七言古诗","c":["放情幽兴付渔蓑，潇洒林亭乐太和。","每踏芳丛寻古句，闲乘小艇泛清波。","烟凝翠黛山疑雾，风蹙斜纹水似罗。","深砌蛩鸣残暑退，高梧蝉噪晚凉多。","炎云渐敛秋将近，霁景才看夏欲过。","静听菱歌音韵好，何须萧鼓济分河。"]},{"t":"初秋咏月影溪声","f":"七言绝句","c":["月挂半空飘素影，溪流一派送秋声。","溪声入耳原无意，月影穿帘似有情。"]},{"t":"秋日登朗吟阁寓目","f":"七言律诗","c":["缥缈遥峰带夕曛，晴光历历望中分。","桥移虹影当溪卧，风度蝉声隔岸闻。","数片晚霞三径菊，一潭秋水半床云。","高亭避暑才吟罢，又听金飙送雁群。"]},{"t":"秋夜述怀","f":"五言绝句","c":["桂香盈院宇，银汉净无垠。","耿耿难成寐，澄怀虑兆民。"]},{"t":"立春","f":"五言律诗","c":["晴光当户映，淑气逐人来。","冻草苏先觉，枯条暖自催。","荐新红菜甲，应候绿英梅。","为问迎春吏，农畴几处开？"]},{"t":"初夏西苑游瞩","f":"七言律诗","c":["前廷午退紫宸班，回辇寻幽竹石间。","一息不停新绿水，四时相对旧青山。","溪烟澹荡平台晚，林影参差夕照间。","鸟识禁园栖托稳，每看飞去又飞还。"]},{"t":"蓬莱洲咏古","f":"七言律诗","c":["唐家空筑望仙楼，秦汉何人到十洲。","尘外啸歌红树晚，壶中坐卧碧天秋。","庙堂待起烟霞侣，泉石还看鹤鹿游。","弱水三千休问渡，皇家自有济川舟。"]},{"t":"万方安和轩秋日作","f":"七言律诗","c":["霜飙飒飒度枫林，红叶如花碧水浔。","每感金行成物品，常推道念格人心。","翱翔彼鸟呼群乐，含哺吾民鼓腹吟。","四野喜看农事毕，聿修百职政维今。"]},{"t":"中秋","f":"五言律诗","c":["冰轮圆此夕，华彩耀寰瀛。","云雾长空净，乾坤一色明。","金波帘影动，玉露桂香清。","海内同欢节，家家笑语声。"]},{"t":"感秋","f":"七言律诗","c":["清秋玉宇净纤尘，银汉澄辉物候新。","雁陈排空横紫塞，桂香绽露报霜辰。","涓涓石濑溪流月，瑟瑟金飙风度蘋。","抚景不禁兴感慨，啼蛩无那送声频。"]},{"t":"雨后郊外泛舟","f":"七言律诗","c":["雾敛西岩暑气消，微风正好泛轻桡。","新晴燕雀低临水，积雨菰蒲密碍桥。","到处湖山惟竹月，数家烟火尽渔樵。","瀛洲宛在京畿右，不羡仙家去路遥。"]},{"t":"夏夜","f":"七言律诗","c":["画槛临池柳半遮，纤尘不到静无哗。","惠均方物分丹荔，冷浸盘冰剖碧瓜。","风送荷香来枕畔，月移竹影上窗纱。","数声鹤唳清诗思，银汉流辉夜景赊。"]},{"t":"新晴遣兴","f":"五言律诗","c":["远水明斜照，残霞有似无。","岚光浮树杪，桥影射池隅。","鹊唱平安曲，荷呈如意珠。","天然诗里画，懒绘辋川图。"]},{"t":"偶题","f":"七言绝句","c":["秋宵噭噭云间鹤，古调泠泠松下琴。","皓月清风为契友，高山流水是知音。"]},{"t":"秋夜","f":"七言律诗","c":["瑟瑟西风起白蘋，临池曲槛净无尘。","苑供火枣盈盘赤，枝缀葡萄下架新。","雨后晚凉清几案，山空夜气静心神。","悠然一缕炉烟细，虚室忘言契道真。"]},{"t":"河沙","f":"五言律诗","c":["河沙千世界，只此一微尘。","为见禽鱼乐，方知天地春。","无心还是妄，有说却非真。","识得西来意，时时景物新。"]},{"t":"自遣","f":"古风","c":["清昼梵风传磬，中宵禅月满床。","声色是我得会，色声与我两忘。"]},{"t":"偶成","f":"七言绝句","c":["斗柄旋东月建寅，余寒敛尽岁云新。","鸟歌花舞真如相，水绿山青自在人。"]},{"t":"自疑","f":"七言绝句","c":["谁道空门最上乘，谩言白日可飞升。","垂裳宇内一闲客，不衲人间个野僧。"]},{"t":"题画","f":"七言绝句","c":["一派涛声涌渡头，寒江漠漠楚天秋。","可怜两岸萧条柳，似为行人绾去舟。"]},{"t":"雨后对月偶成","f":"古风","c":["碧天一轮荡漾，皎洁万里晴辉。","夜漏沉沉院宇，寂然默会圆机。"]},{"t":"深柳读书堂避暑","f":"七言律诗","c":["三庚节届祝融临，闲对明窗阅古箴。","树杪莺喉调妙曲，槛边蝶翅舞芳襟。","嫩荷香远风频递，深柳阴重暑不侵。","移榻帘前何所思，要赓解阜入虞琴。"]},{"t":"夏夜即景","f":"五言律诗","c":["松荫溪流静，雨余峰影寒。","夜深尘虑涤，河耿漏声残。","清韵风敲竹，幽香露滴兰。","长空神妙合，心月会双丸。"]},{"t":"中秋夜","f":"七言律诗","c":["月华当户彩盈盈，九十高秋序正平。","他夕偏宜兹夕好，今年却胜去年明。","辉含珠露凝仙液，光委金波满玉觥。","闻说蟾宫多桂子，天香时觉拂衣清。"]}]};